D.SpellTexts[112060]={Description={["8560619ee14fba23:115"]="煞能在操纵这个灵魂。它在被害的影踪派防御者附近进行净化仪式之前，无法被击败。"},Aura={["c8938cc89645d847:85"]="在被害的影踪派防御者附近进行净化仪式之前，无法被击败。"}}
