D.SpellTexts[112868]={Description={["872d17f2931bf5e3:81"]="召唤一个破坏魔为你作战，破坏魔能催眠对手，阻止其发动攻击。"},Rank={["1ca31bc40679b1c1:6"]="召唤"}}
