D.SpellTexts[113843]={Aura={["2bd423572aa94136:22"]="愤怒加剧。"}}
D.SpellTexts[113845]={Aura={["da0a3012c62bcd87:15"]="夺命弓。"}}
D.SpellTexts[113846]={Aura={["0dc51b71848bc734:26"]="近战攻击造成流血效果。"}}
D.SpellTexts[113865]={Aura={["6d9a4e5a1dabef21:13"]="无敌。"}}
D.SpellTexts[113902]={Description={["7bb67a288930ad2f:33"]="激活最近的恶魔传送门。"}}
D.SpellTexts[113942]={Description={["40aa9a448662802f:54"]=S[20636]},Aura={["40aa9a448662802f:54"]=S[20636]}}
D.SpellTexts[113949]={Description={["3c3366adf84cfb1e:29"]="将水泼向懒惰的猢狲。"}}
D.SpellTexts[113955]={Aura={["c6cced78adcd8c8d:38"]="活儿还没干完就消极怠工。"}}
D.SpellTexts[113957]={Description={["837cbf6e282930cb:59"]="在昆森村的篝火旁使用，烹制炖穆山兽尾。"},Aura={["33f43376de841607:22"]="烹制炖穆山兽尾。"}}
D.SpellTexts[113967]={Description={["76dc61774d68de6e:45"]="朝敌人喷射棘刺，造成自然伤害。"}}
D.SpellTexts[113968]={Description={["a3ddfd82eed7064f:330"]="熊猫人有着悠久的饮茶历史。虽然他们非常看重泡茶的工序，但如何品茶的秘诀也同样珍贵。这套简单的茶具制造于魔古统治时期，曾在那个痛苦的暴政时代为它的主人带来一些慰藉。虽然已经碎裂了，但它提醒着人们，不要忘记生活中的小乐趣。"}}
D.SpellTexts[113971]={Description={["89f98ce6b1ebbba1:141"]="熊猫人热爱游戏，尤其是象棋。这种古老的游戏从第一位熊猫人皇帝时期风靡至今。这是古代棋具的典型代表。"}}
D.SpellTexts[113972]={Description={["74da56d29dbbf067:503"]="一对用黑檀和白玉雕成的酒杯。为了降低烈酒的副作用，酒中仙‘阴阳拳’郭乾斗酿制出了阴阳调和的美酒——白灵酒和玄思酒。按照特定的比例饮下这两种酒时，饮酒者会感到飘飘欲仙，但又不至于像饮用普通烈酒时那样丧失判断力和自制力。可惜的是，这位酿酒仙师的秘方已经失传了，但这些精美的酒杯仍让人想起他那精湛的技艺。"}}
D.SpellTexts[113973]={Description={["c6c4dc14c74a51c3:531"]="这是神秘的酿酒仙师云壬曾使用过的众多拐杖之一。云壬先天失明，但他的其余四感却远超常人。因此，他发现当时的酒大多苦涩粗劣。经过数年的实验，他最终改进出了四大美酒，每种对应一感。但是，他总是无法开发出能够同时具备四感之美的酒。直到晚年，他才研究出了大师级的秘方，“四德酒”。这是他那个时代最伟大的发现。遗憾的是，这一秘方失传已久，因为云壬的字迹实在太难辨认了。"}}
D.SpellTexts[113974]={Description={["97508f5b0ce32a8a:439"]="这个酒桶上的心形龙头表明这是已故的酿酒仙师“伤心客”尹心卧的遗物。数代之前，这位著名的酿酒仙师酿造出了‘逸心酒'。这种调和酒能让饮用者感受到温暖和幸福。据说，尹心卧十分喜爱自己酿造的酒，以至于每卖出一桶酒，他都要伤心落泪。所以他很可能就对着这只酒桶痛哭过。而你看着空空如也的酒桶，也不禁有些伤心。"}}
D.SpellTexts[113975]={Description={["a9151b6a1b8ad485:212"]="镜面上的玻璃已经不见了，反面的精美铜质雕花描绘了祥瑞朱鹤的形象。周围的铭文写着：“赠林/当窗理云鬓/对镜贴花黄/姚”。"}}
D.SpellTexts[113976]={Description={["5b930dc3f3abd694:294"]="这种瓷俑大多用于陪葬，为悲伤的亲人们带去一点慰藉。这个雕像的原型是一位年轻美丽的熊猫人游学者——林媚。根据镌刻于雕像上的铭文记载，她死于猢狲皇帝里克提克统治时期。当时，一场可怕的热病横扫了四风谷，也夺走了林的生命。"}}
D.SpellTexts[113977]={Description={["ded2123b0d8cd642:391"]="一整套铜质罐子，上面清楚地刻着标签，用于储存各种神秘强大的草药。虽然大部分草药的功效尚不清楚，但保存药罐的盒子上有一块名牌，表明它们属于一位名叫姚·坚爪的药剂师。在四风谷，这位妙手仁心的大夫仍然是健康与生命的代名词。据说，这位大夫曾有过一段心碎的往事，所以终生未婚。"}}
D.SpellTexts[113978]={Description={["6a1e71e5ffbaea1c:352"]="这颗玉珠周围环刻着一条衔尾蛟龙的形象。球面上的铭文写道：“万物化生，此谓之道。”这颗珠子雕刻于熊猫人皇帝苏·心眼时期，是向青龙玉珑致敬的艺术品。衔尾蛟龙的造型象征着青龙每百年重生一次的习性。至今，她还会在翡翠林的青龙寺中赐予人们智慧与洞察力。"}}
D.SpellTexts[113979]={Description={["163c983ca255f33d:284"]="一卷厚厚的帆布，高举之时，迎风招展的旗面上承载着熊猫人皇帝的骄傲纹章。底部长长的皮带上坠着沉重的铁环，将旗帜绷得紧紧的。每一条皮带上都绣着给掌旗官的警句：“沧海横流，方显英雄本色。”"}}
D.SpellTexts[114302]={Rank={["7f5c1454467b72e1:10"]="变形"}}
D.SpellTexts[113980]={Description={["6d5cefa1f8ddd674:489"]="这把长柄竹伞精美的油纸伞面竟然能在漫长的雷掌王朝中完好的保存下来，这不能不说是一个奇迹。伞面的下半部画着一片漆黑的乌云，上半部则是一轮红日喷薄而出。乌云边上用优美的书法写着一个短句：“浮云难蔽眼，赤日常在心。”在熊猫人心目中，朱鹤赤精一直是希望的象征。华美壮丽的朱鹤寺就坐落在四风谷南方的险恶丛林中。"}}
D.SpellTexts[113981]={Description={["5c79ccecdfb6cf5f:525"]="这柄威武的长矛铸造于赞达拉巨魔之战时期，挥舞起来格外轻便。脱漆的木柄上布满了深深的刮痕，但矛尖却毫发无损。根据这件武器的长度以及铸造时间判断，你觉得这是一柄骑在翔龙上时使用的武器。褪色的木柄上写着一行警句：“胜人者力，自胜者强。”白虎雪怒以勇猛暴烈而著称。坐落在昆莱山上的白虎寺中，最有潜力的战士们学习靠自律来节制自己的力量。"}}
D.SpellTexts[113982]={Description={["86cc01588e7cbcdd:199"]="以生铁铸造，再注入制伏与痛苦的法术能量。魔古族使用这些内壁上带有倒刺的镣铐来折磨被他们奴役的民族。虽然法术力量早已消散，但这件残酷的刑具依然令你背脊发凉。"}}
D.SpellTexts[113983]={Description={["c0a74332479db4dd:423"]="与其他“低等种族”还需要后天学习如何使用魔法不同，魔古族的魔法能力是与生俱来的。根据已知的魔古族施法方式来看，他们的施法者显然与已知的任何一种施法者，如法师和术士，都大相径庭。他们特别擅长血肉塑形和灵魂捕获类的法术。艾泽拉斯的现代种族都很难理解这块石头内残留的法术力量。而最奇怪的是，符文周围的一些符号与泰坦语十分相似。"}}
D.SpellTexts[113984]={Description={["de3b218414c52ab7:342"]="在魔古族已经找不到可以奴役的活人来为他们作战的时候，他们决定转而创造出一支由拟人构造体组成的大军来为他们征战。由于这些陶俑战士可能会休眠数个世纪之久，所以很难查清这个战士是何时制造或使用的。不过，这条断臂底部的刻痕表明，它是在战斗中被毁坏的。"}}
D.SpellTexts[113985]={Description={["a8d172b764dfa1e4:116"]="这根鞭子很像某些远古大型生物的脊椎。许多魔古族的奴隶都曾在这根鞭子下皮开肉绽。"}}
D.SpellTexts[113986]={Description={["c9a0b44609bec955:123"]="这个玉质徽章上刻有皇冠和交叉的闪电。它是第一位魔古皇帝雷神麾下的士兵们所佩戴的勋章。"}}
D.SpellTexts[113987]={Description={["3a519ab4f38e8dc3:200"]="这部法典以第一帝国的统一语言撰写而成，并精心雕刻在石板上。在条文的顶端写着，煽动罪、暴动罪和叛乱罪将被处以凌迟弃市之刑。"}}
D.SpellTexts[113988]={Description={["f9e6e048f0776a07:110"]="这个巨大的铁制护符简直和战斧一样重。魔古战士们经常佩戴这种“首饰”以彰显他们的力量。"}}
D.SpellTexts[113989]={Description={["8e522cbf9db70e0e:100"]="这个烙铁上带有个小型魔古军阀的纹章。它可不是用在家畜身上的，而用在人形奴隶身上的。"}}
D.SpellTexts[113990]={Description={["56409aa7f3d24d52:293"]="这是一枚魔古皇帝呙统治时期的货币，这位皇帝有着一长串名流史书的功绩。这枚钱币的背面反映了魔古帝国的朝代更迭。在这个血腥的过程中，前朝统治者在被推翻后必死无疑。从各方面看，古代魔古政权都是建立在强权与阴谋之上的优胜劣汰的机制。"}}
D.SpellTexts[113991]={Description={["4160350185e824fc:173"]="虽然掌握着强大的魔法，但魔古族还是喜欢驱使奴隶来建造雄伟的纪念碑。这个基座上记载了为了建造这座纪念碑所牺牲的奴隶的数量。"}}
D.SpellTexts[113992]={Description={["ef359b864b403a83:208"]="这座雕像雕刻于短命的魔古皇帝康的统治时期，是当时为了将魁麟仆从封印入小石头里而进行的实验的一部分。由于被封印的魁麟力量会严重削弱，这项实验最终被放弃了。"}}
D.SpellTexts[113993]={Description={["a89404fd3370c716:66"]="一个熊猫人的解剖假人，用于研究处刑技巧。"}}
D.SpellTexts[113996]={Description={["ef361d956860ab6a:63"]="使用白骨护甲围绕施法者，吸收一次白骨攻击。"},Aura={["b66180c35c75db68:24"]="吸收下一次白骨法术。"}}
D.SpellTexts[113998]={Aura={["8b612bfa54f8fb41:22"]="召唤次级煞魔。"}}
D.SpellTexts[114000]={Aura={["979997f4ce4e183b:8"]=S[13681]}}
D.SpellTexts[114007]={Description={["50fcfbe4fe38b7f5:70"]=S[3716]},Aura={["50fcfbe4fe38b7f5:70"]=S[3716]}}
D.SpellTexts[114009]={Aura={["c1bfbde37f0019f2:38"]="造成火焰伤害，并随时间而变大。"}}
D.SpellTexts[114019]={Description={["65624ef462658c1d:29"]="将一个敌方目标击飞。"}}
D.SpellTexts[114028]={Aura={["091d80915f1f08ea:24"]="反射对你施放的法术。"}}
D.SpellTexts[114037]={Aura={["979997f4ce4e183b:8"]=S[13681]}}
D.SpellTexts[114038]={Aura={["f4565d9c708faf19:6"]="致盲。"}}
D.SpellTexts[114050]={Aura={["5cac4dc72a18b33c:78"]="变身为强大的火焰升腾者。闪电链转变为熔岩弹射。"}}
D.SpellTexts[114052]={Aura={["544754fe6f502793:106"]="变身为强大的流水升腾者。你所造成的所有治疗效果都会被复制，并由附近的所有盟友平均分摊。"}}
D.SpellTexts[114060]={Description={["3ed45f05182e94c0:99"]="将会触发随机效果！有一定几率恢复生命值或战斗资源。只能在翡翠林的珍珠湖使用。"}}
D.SpellTexts[114061]={Description={["717c08884e200683:51"]=S[7112]},Aura={["717c08884e200683:51"]=S[7112]}}
D.SpellTexts[114065]={Aura={["8f319f175f4f8cd0:48"]="你骑着一头臭熏熏且需要清洗的落跑牦牛。"}}
D.SpellTexts[114072]={Aura={["31d21832e003dd37:31"]="使用清新的松香给牦牛熏香。"}}
D.SpellTexts[114078]={Description={["8bbe0a126a4d74cd:35"]="扑向目标，咬他的脖子。"},Aura={["65c7904d9ff272d2:102"]="一只邪恶、残忍、脾气暴躁的啮齿动物正在咬你的脖子。因恐惧而逃跑，治疗效果降低100%。"}}
D.SpellTexts[114083]={Description={["fd7a6d9be253f6c2:64"]="治疗效果被复制，并在附近所有的盟友中平均分配。"}}
D.SpellTexts[114085]={Aura={["245353bba398987c:14"]="……成河。"}}
D.SpellTexts[114090]={Description={["39acb0e6029b990f:47"]="右键点击以召唤或解散你的暗月小兔。"}}
D.SpellTexts[114111]={Aura={["cd4c34c8a358fae1:8"]="嘲讽。"}}
D.SpellTexts[114143]={Description={["8d4389a4b3b2f16b:37"]="向目标发射一连串香蕉。"},Aura={["8c66b8f2753bc37d:21"]=S[2136]}}
D.SpellTexts[114144]={Description={["b4555f8bd6357204:23"]=S[20534]}}
D.SpellTexts[114145]={Description={["9fb850100427e5b9:37"]="在目标范围内对敌人造成伤害。"}}
D.SpellTexts[114146]={Description={["385b64a957aeaf98:51"]="地上涌现一个愤怒之池。不要站在里面！"}}
D.SpellTexts[114147]={Description={["63d89a272bf667b0:28"]="向目标冲锋并将其击退。"}}
D.SpellTexts[114159]={Description={["fb20806e70ffbb3b:39"]="学习血色十字军的教义。"},Aura={["fb20806e70ffbb3b:39"]="学习血色十字军的教义。"}}
D.SpellTexts[114171]={Description={["c236aa78f2f9faf5:38"]=S[2144]},Aura={["c236aa78f2f9faf5:38"]=S[2144]}}
D.SpellTexts[114172]={Description={["8784315269e6b1d7:41"]="伤害性的怒之煞从地面涌出。"}}
D.SpellTexts[114209]={Description={["be227378fa5f0be7:87"]="使空气中充满牦牛之息，对附近的敌人造成自然伤害，并恐吓野牛人。"}}
D.SpellTexts[114215]={Aura={["84ed7a04c5da08ab:34"]="骑士几乎控制不住坐骑。"}}
D.SpellTexts[114233]={Aura={["50a6dc1a6386884d:36"]="运送一批重要的青玉。"}}
D.SpellTexts[114239]={Aura={["141775f1c6bd0fb0:26"]="免疫移动速度限制效果。"}}
D.SpellTexts[114255]={Aura={["996686900a1b6d85:37"]=S[478]},Rank={["7c9c6d99938d56b6:4"]="触发技能"}}
D.SpellTexts[114259]={Description={["56b9f9653841f9fa:63"]="驯犬者布兰恩命令顺从的猎犬随机攻击一个敌人。"}}
D.SpellTexts[114262]={Description={["143e0fa425963f4f:45"]="通过邪恶魔法复活目标尸体。"}}
D.SpellTexts[114282]={Description={["e10eadfe51ed4e09:25"]="变形进入树人形态。"},Aura={["94c76f76abc1da1b:61"]=S[5079]},Rank={["7f5c1454467b72e1:10"]="变形"}}
D.SpellTexts[114285]={Description={["4e54a9b3469d2352:57"]="击退施法者面前的所有人，并使他们耳鸣。"}}
D.SpellTexts[114288]={Description={["c73cc469618674b6:120"]="施法者选择多个位置来放炸药。如果螳螂军火爆炸冲击到这些炸药，这些炸药就会被引爆。"}}
D.SpellTexts[114291]={Aura={["979997f4ce4e183b:8"]=S[13681]}}
D.SpellTexts[114297]={Description={["52a550ffe570122e:29"]="可以用来削弱邪煞残影。"},Aura={["19729b6f7415b9a8:19"]="削弱邪煞残影"}}
D.SpellTexts[114301]={Description={["b878ed18b0043313:131"]="你的枭兽形态现在以星界形态出现，所有加成不变，但角色外观将呈现为普通人形形态的星界加强版。"},Rank={["65a8ac8be29b153c:7"]="平衡"}}
D.SpellTexts[114333]={Description={["aacac3c65a536d63:34"]="你在水栖形态下将变成一条虎鲸。"}}
D.SpellTexts[114355]={Description={["fac8a1bd0cd149f2:42"]=S[5440]},Rank={["9be076a0b7821de7:7"]="被动"}}
D.SpellTexts[114370]={Aura={["a47ed079942974ae:21"]="那只熊猫人喝得烂醉如泥！"}}
D.SpellTexts[114404]={Aura={["233d7561249f9f8c:29"]="被附近的虚空触须定身。"}}
D.SpellTexts[114414]={Aura={["e6f7f56d69d7b56a:72"]="被一片召唤出来的先祖之魂迷雾笼罩。免疫所有伤害和效果。"}}
D.SpellTexts[114427]={Description={["4b14145f815e7684:26"]="喷射一股除草剂。"},Aura={["19d97f08dff59a21:19"]="喷射除草剂。"}}
D.SpellTexts[114429]={Description={["4b14145f815e7684:26"]="喷射一股除草剂。"},Aura={["19d97f08dff59a21:19"]="喷射除草剂。"}}
D.SpellTexts[114430]={Description={["514ffa5da1092354:128"]="种植影光松露孢子。影光松露只能在昆森村的高海拔地区或摩天山脊生长。"}}
D.SpellTexts[114431]={Description={["1f02877c69de8435:50"]="除去日歌农场上的农田里的杂草。"},Aura={["25492d1dea149804:39"]="蓝盖现在正在升级日歌农场。"}}
D.SpellTexts[114443]={Description={["761e946839132749:36"]="对5码范围内的所有敌人造成伤害。"}}
D.SpellTexts[114448]={Aura={["6bf95acaa35f419d:21"]="吃了一些坏掉的蔬菜。"}}
D.SpellTexts[114450]={Description={["c737a8cab025368b:38"]="将醋栗交给指定的村民。"}}
D.SpellTexts[114459]={Description={["f1264910cf4eda0d:70"]="将目标压缩并困在一个碳酸气泡中，使其从地面升起来。"},Aura={["d515d33ca96397f5:22"]="在气泡里飞起来！"}}
D.SpellTexts[114460]={Description={["fe14abfd301147a2:75"]=S[17329]},Aura={["fe14abfd301147a2:75"]=S[17329]}}
D.SpellTexts[114462]={Description={["f69bfaa4757740a7:19"]="召唤一个风暴图腾。"}}
D.SpellTexts[114466]={Aura={["261c2cc30e0f9d1e:28"]="昏迷，并出人意料地不断打嗝！"}}
D.SpellTexts[114468]={Aura={["da6e34bd38309012:20"]="让人一蹦三尺高！"}}
D.SpellTexts[114472]={Aura={["b9951b0b07c4e470:55"]="被定身。反射法术，反击造成双倍伤害。"}}
D.SpellTexts[114474]={Description={["5fb037796ef3e298:49"]=S[5758]}}
D.SpellTexts[114476]={Description={["b89f158968751916:52"]="立即对任何向你发动近战攻击的敌人进行反击。"}}
D.SpellTexts[114480]={Aura={["d86312dd54a6efe2:14"]=S[16999]}}
D.SpellTexts[114483]={Description={["3705c273d4fa927a:51"]="移走日歌农场上农田里的货车。"},Aura={["6631281e93de11a5:45"]="玉儿·采苇现在正在升级日歌农场。"}}
D.SpellTexts[114486]={Description={["4f968e2bf17230d2:10"]="敲打。"},Aura={["4f968e2bf17230d2:10"]="敲打。"}}
D.SpellTexts[114495]={Description={["5dee72392dbb1c9c:36"]=S[7622]},Aura={["5dee72392dbb1c9c:36"]=S[7622]}}
D.SpellTexts[114512]={Description={["f52fda1dffee0e48:55"]="让目标减速，阻止他们踩中土拨鼠。"},Aura={["a444e7720ff2f4e5:55"]="被讨厌的昆虫减速。被减速时你无法踩中土拨鼠。"}}
D.SpellTexts[114517]={Description={["9e1d1cd54ee49756:14"]="杀死害虫！"},Aura={["05cc2b27cbb52398:34"]="杀死维卡维卡地里的害虫。"}}
D.SpellTexts[114535]={Description={["5cb93179762914f8:49"]="古代土地精小径上的祝福施加于你，提高你的速度。"}}
D.SpellTexts[114568]={Aura={["979997f4ce4e183b:8"]=S[13681]}}
D.SpellTexts[114569]={Description={["f69bfaa4757740a7:19"]="在施法者身一根风暴图腾。"}}
D.SpellTexts[114570]={Description={["dc3847cbfa7e72f2:117"]=S[2154]},Aura={["8e4cd846a745ca43:28"]="一个战争机器发现你了。"}}
D.SpellTexts[114572]={Description={["44a820ae1e7fd029:43"]="大贝莎追逐目标，并对嘲讽免疫。"},Aura={["62123c62d69e59bb:48"]="大贝莎找到了目标，无法被嘲讽。"}}
D.SpellTexts[114576]={Description={["ed02cd23eb675260:30"]="扔一个菜瓜在地上。"}}
D.SpellTexts[114586]={Aura={["f77768201b1d43d3:55"]="被甜瓜里的混合物毒到。暂时变得虚弱了。"}}
D.SpellTexts[114587]={Description={["d355520e8851c8b3:15"]="骑乘老方的风筝。"},Aura={["e51575398a5c80de:29"]="你正在骑乘农夫老方的风筝。"}}
D.SpellTexts[114599]={Aura={["9a2cd2fa3045010b:9"]=S[15704]}}
D.SpellTexts[114610]={Description={["02ad55179da70474:35"]="你手中捧着师父的焰火。"},Aura={["02ad55179da70474:35"]="你手中捧着师父的焰火。"}}
D.SpellTexts[114624]={Description={["3adec19411bf6751:49"]="除去老愚农场的农田里的石头。"},Aura={["b5c5d68d024677d2:46"]="郝瀚·泥爪现在正在升级日歌农场。"}}
D.SpellTexts[114644]={Description={["abeb08da5af2f953:141"]="每当你在朱鹤寺里杀死一个煞魔，安度因就为你恢复一部分的生命值和法力值，并鼓舞15码范围内绝望的赤翼守护者。"},Aura={["ffd3b25d8aafb3ce:220"]="受到安度因·乌瑞恩的援助。\r\n\r\n每当你在朱鹤寺里杀死一个煞魔，你将恢复一部分的生命值和法力值，并鼓舞附近绝望的赤翼守护者。\r\n\r\n效果与消灭的煞魔成正比。"}}
D.SpellTexts[114651]={Description={["f39fc87f4737cba6:134"]=S[15347]},Aura={["f39fc87f4737cba6:134"]=S[15347]}}
D.SpellTexts[114652]={Description={["f7a242b56a081ade:15"]=S[12314]},Aura={["edddad85a0fe12a6:23"]="你提着一只丢失的母鸡。"}}
D.SpellTexts[114661]={Description={["067ca483c8ecae6a:37"]="你捉住了农夫老周的一头牦牛。"},Aura={["3b760068a81d26bb:35"]="带着这些牦牛回去找指挥官。"}}
D.SpellTexts[114663]={Description={["00c5985b5c8e00e4:91"]="布兰琪聚集真气，放置一个宁静之环，站在其中可恢复生命值和法力值。"}}
D.SpellTexts[114667]={Description={["f21b3e7c15e53b4b:32"]="把丢失的母鸡带回它的鸡窝。"}}
D.SpellTexts[114668]={Description={["f7a242b56a081ade:15"]=S[12314]}}
D.SpellTexts[114669]={Description={["dd605ef45d429961:29"]="将发情的公鸡浸泡在水中。"}}
D.SpellTexts[114670]={Description={["f7a242b56a081ade:15"]=S[12314]},Aura={["941c680a004adc83:31"]="你提着一只发情的公鸡。"}}
D.SpellTexts[114671]={Description={["3e2d6622e670bc8b:36"]="把这只野生农场小鸡赶出去！"}}
D.SpellTexts[114672]={Description={["f7a242b56a081ade:15"]=S[12314]},Aura={["889ce2197f3b424e:34"]="你提着一只野生农场小鸡。"}}
D.SpellTexts[114675]={Description={["b3fe414e5c98db6b:32"]="冲击目标造成自然伤害。"}}
D.SpellTexts[114676]={Description={["6f2ab666f5180dfb:42"]="揭露伪装土拨鼠的真面目。"}}
D.SpellTexts[114677]={Description={["f7a242b56a081ade:15"]=S[12314]},Aura={["824bd659c81b459a:31"]="你提着一只伪装的土拨鼠。"}}
D.SpellTexts[114695]={Rank={["1d8dabcd9bb659ec:6"]="天赋"}}
D.SpellTexts[114706]={Description={["f1fec0b96e2e8726:76"]=S[2391]}}
