D.SpellTexts[123933]={Description={["bfdab6bdc1e190e4:68"]="多年的囚禁让乔古鲁在追捕猎物时非常暴躁。"},Aura={["ae31aeda99999873:76"]="移动让乔古鲁感到很难受。\r\n\r\n别惹雪人——他要是发怒，你可受不了！"}}
