D.SpellTexts[124102]={Description={["84bd61eb8fe32472:295"]="“这是一枚魔古皇帝呙统治时期的货币，这位皇帝有着一连串的攻击。这枚钱币的背面反应了魔古帝国的朝代更迭。在这个血腥的过程中，前统治者在被推翻后必死无疑。在各方面看，古代魔古政权都是建立在强权与阴谋之上的精英政府。”"}}
