D.SpellTexts[124201]={Description={["df2d1b4458159b8f:134"]="向目标位置掷出毒性混合剂，立即造成伤害。对已被麻痹的敌人尤其有效。\r\n\r\n混合多种毒药会造成剧烈反应。"}}
