D.SpellTexts[126434]={Description={["119b271a426667b3:105"]="你为土水派熊猫人而战。在地下城中战斗获得的所有声望值，也同样可以提升你在土水派熊猫人中的声望。"},Aura={["03454608e299cff5:63"]="在地下城中战斗获得的所有声望值，也同样可以提升你在土水派熊猫人中的声望。"}}
