D.SpellTexts[126455]={Description={["360a73c669ab312b:155"]="在牢非的灵魂的攻击围内的所有熊猫人武僧的残影都立即被击败。\r\n最暴虐的魔古暴君牢非对一拥而入自称叛军的人而言并不陌生。"}}
