D.SpellTexts[126459]={Description={["72b8185394cc7ba0:158"]="组装强大的布林顿4000，这是个拥有无穷财富的机器人。他喜欢别人叫他布林。布林会向每个与其谈话的人分发随机的一份礼物，但每天只分发一次。持续10分钟。"}}
