D.SpellTexts[127325]={Description={["fdc18326fc72b761:82"]="召唤热心呆瓜，它会为你劫掠东西，并将礼物带回来。只能在潘达利亚使用。"}}
D.SpellTexts[127330]={Aura={["a1b324faac285e2d:177"]="在瑟拉维斯岛上受到守卫保护时，你会获得隐形帷幕的保护。进入战斗、受到伤害、放置炸弹和骑乘将解除你的潜行状态。"}}
D.SpellTexts[127338]={Description={["bfc4eef62504aefb:52"]="唤醒附近死亡的希克提克螳螂妖体内残留的憎恨。"}}
D.SpellTexts[127344]={Description={["dbbfab6d1f851574:85"]="使一具目标尸体在一阵撞击中爆炸。无法对机械或元素生物的残骸使用。"}}
