D.SpellTexts[127355]={Description={["f743f4ba4f9ae91d:47"]="统御目标的心灵，使其为你作战。"},Aura={["a2fb63d3a214276a:55"]="被控制。只在恐惧废土中有效。持续10分钟。"}}
D.SpellTexts[127357]={Aura={["23c507ea457a9829:140"]="高优先级的目标。被杀死时获得优异力量、敏捷和耐力。必须处于搜寻与摧毁效果下才能获得这个增益效果。"}}
