D.SpellTexts[128112]={Description={["613d622f3f752832:172"]="克尔鲁克把你包裹在音速之盾中，并将你发射到目标位置。落地时，你的护盾爆炸，对附近10码范围内的所有敌人造成伤害（对玩家控制的敌人造成一半伤害）。"}}
