D.SpellTexts[130534]={Aura={["39073f7dc85891c4:23"]=S[17378]}}
D.SpellTexts[130546]={Description={["b46bcac1c820e960:65"]="对加尔鲁什尔前哨站码头的火药桶开火，清理出通往加图尔的道路。"}}
D.SpellTexts[130577]={Description={["c690cf5141b2fb14:43"]="可怕的恶臭造成周期性的自然伤害。"},Aura={["c690cf5141b2fb14:43"]="可怕的恶臭造成周期性的自然伤害。"}}
