D.SpellTexts[130678]={Description={["8ae61a0ac4bbef75:67"]="召唤一头不听话的阳痕巨兽。这是一种非常快的坐骑。"},Aura={["86ebbc7ee7bfefad:8"]=S[6092]}}
D.SpellTexts[130696]={Description={["11f7df002100e8b3:48"]="将施法者传送到翡翠林的蜜露村。"}}
D.SpellTexts[130700]={Description={["4edca8d0e0834f79:154"]="攻击者对施法者打出爆击时，他们有一定几率获得毁灭浩劫效果影响，每秒造成暗影伤害，并且每层效果可使其造成的伤害提高Y点。"},Aura={["c91da4936bb16f18:68"]="受到爆击攻击时，攻击者有一定几率获得毁灭浩劫效果。"}}
D.SpellTexts[130702]={Description={["5d091e4d58bcc7da:47"]="将施法者传送到翡翠林的坡东村。"}}
D.SpellTexts[130726]={Description={["2d61699b9faa01d6:45"]="右键点击以召唤或解散你的翡翠触须。"}}
D.SpellTexts[130730]={Description={["6ca77a44c0cb5cdd:60"]="召唤一头咔啡成瘾的骑乘山羊。这是一种非常快的坐骑。"},Aura={["86ebbc7ee7bfefad:8"]=S[6092]}}
D.SpellTexts[130736]={Aura={["c323a20bdef72360:52"]="引爆溃烂之伤会使死亡骑士获得急速效果。"}}
D.SpellTexts[130747]={Description={["373af70089a0e0a3:50"]="尝试装备无限袋。这肯定是一只背包。"},Aura={["c58c65610a176bb8:34"]="正在尝试装备无限袋。"}}
D.SpellTexts[130759]={Description={["a5c5c4881f32491f:38"]="右键点击以召唤或解散你的维纳斯。"}}
D.SpellTexts[130763]={Description={["260af6fa73cdd463:45"]="身受重伤，几乎无法移动。"}}
D.SpellTexts[130772]={Description={["db8a18d7f394590e:72"]="撞击使大门剧烈变形，击倒在大门顶上走动的所有人。"},Aura={["979997f4ce4e183b:8"]=S[13681]}}
D.SpellTexts[130775]={Description={["896969fc3ef35f51:64"]="向当前敌对目标所在区域投出石块，造成物理伤害。"}}
