D.SpellTexts[130825]={Aura={["d6ef7565fb5a55fc:41"]="附近所有生物受到的伤害提高。"}}
D.SpellTexts[130830]={Description={["7b326e7ca6ca412f:77"]="腐烂的芜菁散发着可怕的气味，使附近所有生物受到的伤害提高25%。"},Aura={["5fe61879efbaa7f6:43"]="你闻上去很可怕。\r\n受到的伤害提高25%。"}}
D.SpellTexts[130835]={Description={["40f94572160ad5a9:19"]="灭火。"}}
