D.SpellTexts[130848]={Aura={["2c2df14696569787:36"]="召唤流星冲击随机地点。"}}
D.SpellTexts[130851]={Aura={["c7b83fe95a7a0f3c:8"]="受伤。"}}
D.SpellTexts[130852]={Aura={["670210f07557822d:57"]="这名飞行员身受重伤，情况正在恶化。"}}
D.SpellTexts[130854]={Aura={["9bc1b87c2ced9765:76"]="这位飞行员受了重伤。如不及时采取急救措施的话，他很快就会死去。"}}
D.SpellTexts[130855]={Aura={["a11e18084e72018b:37"]="这名飞行员已经奄奄一息！快给他治疗！"}}
D.SpellTexts[130871]={Description={["4bb1d7cb89b99b30:59"]="对雷霆要塞炸药发射信号弹以摧毁他们的补给品。"}}
D.SpellTexts[130888]={Description={["99d8600967e362e6:14"]="准备完毕后起跳！"},Aura={["99d8600967e362e6:14"]="准备完毕后起跳！"}}
D.SpellTexts[130895]={Description={["dcfec810e7eb9661:54"]="召唤一头横冲直撞的骑乘牦牛。这是一种非常快的坐骑。"},Aura={["4fd7cafff1d3661a:9"]=S[6151]}}
D.SpellTexts[130902]={Aura={["ee28648ba7f39828:37"]="这应该可以消肿。对吧？"}}
D.SpellTexts[130918]={Description={["5f2eeca109128c9c:38"]="在地方放置一只纸鹤，持续1分钟。"}}
