D.SpellTexts[130977]={Aura={["377d95b3a0954cf4:42"]="极不稳定，将在一段时间后爆炸。"}}
D.SpellTexts[130984]={Description={["d4459ba7d260bfee:19"]="在泥水里打滚。呼呼！"},Aura={["ebfc2da0cd77c5b7:28"]="身上沾满了很可能是泥巴的脏东西。"}}
