D.SpellTexts[131113]={Description={["697f3477cde99b3a:32"]="你在旅行形态下将变成一头猎豹。"}}
D.SpellTexts[131116]={Description={["9627e87401cd673b:25"]="可以使用怒击。"},Aura={["9627e87401cd673b:25"]="可以使用怒击。"}}
