D.SpellTexts[131283]={Description={["76522579640781e8:82"]="当你击败一个实力强大的追猎者时，你狩猎其他野兽也游刃有余了。"}}
D.SpellTexts[131288]={Description={["9687612e5585db67:66"]="阻止晴日峰的武僧杀死你，那太粗鲁了。"}}
D.SpellTexts[131307]={Description={["bf13dac46ed6dda7:71"]="使目标宠物小伙伴的体型缩小一倍，只要它停留在主人身边，效果就可以一直持续。"},Aura={["b7aec9d8f79c6767:29"]="魔法小点缩小了体型。"}}
