D.SpellTexts[131467]={Description={["af4a47330e00d9b8:166"]="永久性地在一条腰带上加装一个活化钢带扣，为其增加一个插槽。\r\n\r\n附加腰带扣的装备会成为绑定物品。不能对物品等级高于600的物品使用。"}}
D.SpellTexts[131474]={Description={["b176582681dd2c6b:110"]="面对一片水域时点击此按钮，当水中的鱼漂溅起水花的时候，立刻右键点击鱼漂以捕捉上钩的鱼。你可以将此按钮拖拽至动作条内。"}}
