D.SpellTexts[133801]={Description={["6ac8b52c1c4cf667:188"]="将一面部落旗帜插在地上。旗帜会持续10分钟，最多可插5面旗帜。\r\n\r\n你必须标记为PvP玩家才可以插旗。同样标记为PvP的联盟玩家可试图焚毁你的旗帜。"}}
