D.SpellTexts[135356]={Description={["4b722fb207babd7f:219"]="施法者手持武器和盾牌进入标准的方阵编队。位于同一编队的右翼盟友立即获得同心协力的效果，提高其伤害输出；位于左翼的盟友获得铜墙铁壁的效果，降低其所受伤害。"},Aura={["2d12b04ecf0ab4c5:17"]="方阵编队。"}}
