D.SpellTexts[135408]={Aura={["d42a8c4042305be3:27"]="煽动观众的暴力情绪。"}}
D.SpellTexts[135416]={Description={["2619a012d6a1b0db:114"]="召唤或解散一头可供骑乘的重装狮鹫坐骑。这种坐骑的速度会根据你的骑术等级和所在区域改变。"}}
