D.SpellTexts[135474]={Description={["e055e16dbd8e190c:29"]=S[21040]}}
D.SpellTexts[135499]={Description={["60f05985d9ace4de:49"]="向一名敌人呼出口臭，造成自然伤害。"}}
D.SpellTexts[135503]={Description={["5dd1fb939f5c153a:46"]=S[16907]}}
D.SpellTexts[135508]={Description={["706b7675a6c299be:53"]=S[1109]},Aura={["706b7675a6c299be:53"]=S[1109]}}
D.SpellTexts[135519]={Description={["899ecda879a5d9c7:31"]="冲锋，并造成武器伤害。"}}
D.SpellTexts[135522]={Aura={["28dbea73b9f40022:50"]="攻击命中后提高攻击速度和所受伤害。"}}
