D.SpellTexts[135531]={Description={["9f6088ab1d24edb4:91"]="重塑目标的灵魂，降低其受到的治疗效果，但提高他们对其他人的治疗能力。"}}
D.SpellTexts[135532]={Description={["6e77d510f50e03b5:91"]="将一名敌人的心灵提升到一个危险层级，提高他们的速度，但大幅削弱他们的伤害。"}}
