D.SpellTexts[135540]={Aura={["1258d30e05ba7b5b:64"]="吸收伤害。如果护盾被击破，则被保护的目标会陷入昏迷。"}}
D.SpellTexts[135542]={Aura={["979997f4ce4e183b:8"]=S[13681]}}
D.SpellTexts[135544]={Aura={["0b3a63bb862fc182:54"]="攻击命中后提高伤害输出和所受伤害。"}}
