D.SpellTexts[135596]={Description={["d99367305d7aa2f5:162"]="在闪电炸弹的位置制造静电过载，造成大量伤害并使周围的所有敌人昏迷。\r\n\r\n该静电过载将会终止闪电炸弹。"}}
D.SpellTexts[135599]={Description={["6badedd3ba9412fe:109"]=S[7338]}}
D.SpellTexts[135600]={Description={["40b8ca686afbacbf:59"]="地雷发生爆炸，造成伤害并使周围的敌人昏迷。"}}
D.SpellTexts[135612]={Aura={["e90e33db60fe1b88:30"]=S[15444]}}
D.SpellTexts[135615]={Description={["fb6c7ef289396205:71"]=S[16255]}}
D.SpellTexts[135616]={Aura={["979997f4ce4e183b:8"]=S[13681]}}
D.SpellTexts[135625]={Aura={["01deb941cf9b0d34:6"]=S[18979]}}
D.SpellTexts[135626]={Aura={["f96c647533e2c07c:75"]="将敌人变成青蛙。\r\n在施放高阶妖术时，施法者免疫昏迷和失去控制的效果。"}}
D.SpellTexts[135631]={Description={["8d05dd3f4d2ca054:67"]="产生弹片，并击退前方锥形区域内的敌人。可在移动中使用。"}}
D.SpellTexts[135632]={Aura={["81f980942ae79e37:20"]="这是你的杠杆式火枪！"}}
D.SpellTexts[135643]={Description={["7cbb954511ab7ff4:101"]="真挚好友的死彻底激怒了施法者，使其进入到狂暴状态，增强他们的生命值、伤害和体型。"}}
D.SpellTexts[135650]={Aura={["326ceb275e674bee:19"]="周期性火焰伤害。"},Rank={["1044fc4a16ed2acd:5"]="等级 9"}}
D.SpellTexts[135651]={Description={["a383b7bf4de19f64:41"]="将一颗致命的子弹射入敌人的要害部位。"}}
D.SpellTexts[135652]={Aura={["07e7cd738123c340:51"]="你快要死了！趁现在赶紧跑回堡垒里去！"}}
D.SpellTexts[135679]={Aura={["aec01d22f8c47af3:22"]="牦牛不爱废话。\r\n牦牛大杀四方！"}}
D.SpellTexts[135680]={Description={["59362bb5c3a1647e:72"]="当北部导管开始充能时，雷神会获得静电冲击技能。"},Aura={["241a1dc3e0550a26:49"]="获得静电冲击技能。\r\n对北部导管进行充能。"}}
D.SpellTexts[135681]={Description={["fa56ca61095df812:74"]="当东部导管开始充能时，雷神会获得散射闪电链技能。"},Aura={["8fa307d0f8a9fdf3:54"]="获得散射闪电链技能。\r\n对东部导管进行充能。"}}
D.SpellTexts[135682]={Description={["5dbccdc35dee136e:71"]="当南部导管开始充能时，雷神会获得超载技能。"},Aura={["2380ae118712ae86:48"]="获得超载技能。\r\n对南部导管进行充能。"}}
D.SpellTexts[135683]={Description={["da770e53631860e2:72"]="当西部导管开始充能时，雷神会获得弹跳闪电技能。"},Aura={["e03ccaa1e2ecc8ca:49"]="获得弹跳闪电技能。\r\n对西部导管进行充能。"}}
D.SpellTexts[135688]={Description={["f2a513546d3720b3:52"]=S[9200]},Aura={["3d5f525655e289c5:26"]="每秒造成一次物理伤害。"}}
