D.SpellTexts[136174]={Description={["8223b3855e08a5ac:144"]="施法者进入一个假定的报复姿态。任何一次导致施法者生命值低于最大生命值10%的倍数的伤害，都会立即遭到反击。"},Aura={["9d52a391fcac87f8:32"]="每损失一次10%的生命值便立即反击。"}}
