D.SpellTexts[139199]={Description={["28c2a1a3eb19a9b6:51"]="可进入雷电王座的下水道。"}}
D.SpellTexts[139200]={Description={["3567d068136a5013:28"]="吸取坎雷萨德的邪能。"},Aura={["6ddec70653c1bd61:31"]="吸取坎雷萨德的邪能。"}}
D.SpellTexts[139204]={Description={["a0a018b4474829f3:56"]=S[13298]}}
D.SpellTexts[139220]={Description={["0477d6098b1de27a:84"]=S[13346]},Aura={["0b896447107a7a40:55"]="成功的近战攻击有一定几率造成自然伤害。"}}
D.SpellTexts[139229]={Aura={["c15385e00128ddb3:22"]="变形成为巨魔的模样。"}}
D.SpellTexts[139245]={Description={["92d5541bf56b2f94:37"]=S[9634]}}
D.SpellTexts[139252]={Aura={["f4d3a63f73b78c90:23"]="被闪电追逐。"}}
D.SpellTexts[139267]={Aura={["9d24b67a1cef9f8d:48"]="显示秘藏的遗物！注意金色光柱。"}}
D.SpellTexts[139274]={Description={["9266c3957690acba:33"]="开启通往血腥岔路口的大门。"}}
D.SpellTexts[139275]={Aura={["979997f4ce4e183b:8"]=S[13681]}}
D.SpellTexts[139280]={Description={["1c182ac059716671:22"]=S[12076]}}
D.SpellTexts[139288]={Description={["09764c289305c673:23"]="被肯瑞托魔法冻结。"},Aura={["b5860ea4502851b7:53"]="被肯瑞托魔法冻结。\r\n摧毁符文可打破法术。"}}
D.SpellTexts[139289]={Description={["dd04fed1dbede19e:24"]="被夺日者魔法冻结。"},Aura={["0bf5670d7f8bba62:54"]="被夺日者魔法冻结。\r\n摧毁符文可打破法术。"}}
D.SpellTexts[139294]={Description={["6f7b8727febe31ac:9"]="打、打、打劫！"},Aura={["6f7b8727febe31ac:9"]="打、打、打劫！"}}
D.SpellTexts[139311]={Aura={["76ee396195be0e7a:24"]="疯狂吞噬你的躯体。"}}
D.SpellTexts[139316]={Description={["4f7173cefa88dfc3:34"]="受到伤害时将造成净化效果。"},Aura={["4f7173cefa88dfc3:34"]="受到伤害时将造成净化效果。"}}
D.SpellTexts[139318]={Description={["c3d51d52ca26ae85:49"]=S[18319]},Aura={["c3d51d52ca26ae85:49"]=S[18319]}}
D.SpellTexts[139320]={Description={["0477d6098b1de27a:84"]=S[13346]},Aura={["87a8a04269e69e83:48"]="对附近玩家造成周期性的自然伤害。"}}
D.SpellTexts[139321]={Description={["d040b120bc923c57:65"]="为玩家充能，使其对附近玩家造成自然伤害。"},Aura={["39dcf5a14e73f950:36"]="对附近玩家造成自然伤害。"}}
D.SpellTexts[139322]={Description={["ff497ebdf66d7e82:77"]="为玩家充满电能，使其对附近的盟友造成自然伤害。"},Aura={["39dcf5a14e73f950:36"]="对附近玩家造成自然伤害。"}}
D.SpellTexts[139327]={Description={["ed357a0a67797433:60"]="施法者凝视目标，造成奥术伤害。"}}
D.SpellTexts[139336]={Description={["a708331576ad285c:61"]="施法者向附近的敌人持续不断地射出奥术弹幕。"},Aura={["551984268f20b6eb:35"]="向随机敌人发射奥术箭雨。"}}
D.SpellTexts[139341]={Aura={["0cc04d058279089a:56"]=S[16320]}}
D.SpellTexts[139358]={Aura={["1f80ff51544925c0:9"]="被放逐。"}}
D.SpellTexts[139361]={Description={["1a76eca74d568f42:36"]=S[16248]}}
D.SpellTexts[139362]={Description={["1a76eca74d568f42:36"]=S[16248]}}
D.SpellTexts[139363]={Description={["1a76eca74d568f42:36"]=S[16248]}}
D.SpellTexts[139364]={Aura={["17c599afebc770c0:40"]="进入灵魂世界。\r\n无法被伤害。"}}
D.SpellTexts[139365]={Description={["1a76eca74d568f42:36"]=S[16248]}}
D.SpellTexts[139366]={Description={["ab1b3b72de747eab:40"]="净化目标腐化的邪能魔法。"}}
D.SpellTexts[139382]={Aura={["7215638b6334fe1c:25"]="对附近的所有敌人造成伤害。"}}
D.SpellTexts[139407]={Description={["1b9c1ec4e10d1493:81"]="召唤或解散一条可供骑乘的恶毒角斗士云端翔龙。这是一种飞行坐骑。"}}
D.SpellTexts[139429]={Description={["35328f344b134dc1:46"]="将施法者传送到雷神岛上的紫罗兰高地。"}}
D.SpellTexts[139432]={Description={["875213f644b6dfbf:32"]="将你传送到搏击竞技场。"}}
D.SpellTexts[139434]={Description={["4ca37e66ece33a0d:56"]="将施法者传送到雷神岛上的寻晨者海角。"}}
D.SpellTexts[139437]={Description={["f125bacf0045f688:30"]="将你传送到比兹莫搏击俱乐部。"}}
D.SpellTexts[139442]={Description={["f55a2b5b72833d24:132"]="召唤或解散一条可供骑乘的雷霆蓝晶云端翔龙。这是一种飞行坐骑，需要学习云端翔龙骑士团的云端翔龙骑术。"}}
D.SpellTexts[139443]={Description={["3c92889636f100c3:81"]="煞魔向区域内召唤一阵致命的流星风暴，对被其击中的任意目标造成大量伤害。"}}
D.SpellTexts[139447]={Aura={["aafdd261de4a8384:17"]="召唤流星。"}}
D.SpellTexts[139448]={Description={["cbb854aa8ea59ac9:62"]="召唤或解散一只可供骑乘的季鹍之嗣。这是一种飞行坐骑。"}}
D.SpellTexts[139459]={Description={["3ad61c26b60ddfb7:97"]="消耗一个奥术专注来将你向前推进。只能在雷电之王的藏宝库场景战役中使用。"}}
D.SpellTexts[139462]={Description={["b5bb6205f0fa09b2:54"]=S[5847]}}
D.SpellTexts[139485]={Aura={["60da4e4576306eee:55"]="赞达拉巨魔召唤出一阵强劲的风暴！\r\n无法使用坐骑。"}}
D.SpellTexts[139487]={Description={["49de0ad2a2a387bf:61"]=S[19989]},Aura={["49de0ad2a2a387bf:61"]=S[19989]}}
D.SpellTexts[139488]={Aura={["42ad57cd5148b798:7"]=S[15702]}}
D.SpellTexts[139489]={Description={["f40c48cc136c43bb:103"]="利用魔法改造钥匙，使其能够打开雷电之王的藏宝库场景战役中雷电堡的任意一扇远古之门。"}}
D.SpellTexts[139490]={Aura={["c17d2c2706c53b0e:7"]=S[18936]}}
D.SpellTexts[139492]={Description={["e6224ab54f75f8c4:139"]="在雷电之王的藏宝库场景战役中可被用来漂浮在地砖陷阱上，下落速度减缓，并且可以在水面行走。受到伤害会打断该效果。"},Aura={["2b24642af50e2a27:11"]="漂浮。"}}
D.SpellTexts[139495]={Description={["64432ef20253177d:80"]="在雷电之王的藏宝库场景战役中使用，可用来分散一名敌人的注意力或触发一个陷阱。"}}
D.SpellTexts[139496]={Description={["0f241fd895b8c563:83"]="用黏黏的网覆盖在受害者身上。如果受害者被覆盖足够多的网，则会被包裹起来。"}}
D.SpellTexts[139503]={Aura={["e9ca40dcf08290ed:32"]="施法不会被打断。"}}
D.SpellTexts[139505]={Description={["e71f233ab1463c57:172"]=S[19165]}}
D.SpellTexts[139506]={Aura={["af42b70680ea14b3:7"]="昏迷"}}
D.SpellTexts[139511]={Description={["da8166f0333e973d:81"]="用闪电打击一片区域，造成大量的自然伤害，并将目标轻微击退。"}}
D.SpellTexts[139512]={Aura={["a9433b5c3a2ac343:57"]="像旋风一般攻击附近的所有敌人，并使其流血。"}}
D.SpellTexts[139525]={Description={["747bf9a09e07dc81:30"]=S[6083]},Aura={["747bf9a09e07dc81:30"]=S[6083]}}
D.SpellTexts[139533]={Description={["25578b2ba0a13cf2:40"]="标记一个即将被悟道者伏兵袭击的目标。"},Aura={["4919750881608977:48"]="你被悟道者标记了。准备迎战！"}}
D.SpellTexts[139537]={Aura={["8cc1678f03bf01d6:26"]="黑暗意志正在充能。"}}
D.SpellTexts[139543]={Description={["ecc2e5e306140c40:43"]="一个悟道者伏兵正从该位置绳降。"}}
D.SpellTexts[139553]={Description={["cf4ca27debd7ecc8:18"]=S[1387]}}
D.SpellTexts[139554]={Description={["eab1ed30321403f5:21"]="传送到海箭号。"}}
D.SpellTexts[139556]={Description={["7e45441fef718a96:26"]="传送到白骨庭院。"}}
D.SpellTexts[139557]={Description={["b5faa028bb138b8b:28"]="传送到深红踏浪者号。"}}
D.SpellTexts[139590]={Description={["17ae213a55299e1f:35"]="从目标身上虹吸生命精华。"},Aura={["17ae213a55299e1f:35"]="从目标身上虹吸生命精华。"}}
D.SpellTexts[139595]={Description={["6e2504fe9fa06105:92"]="召唤或解散一只装甲血翼蝠。这种坐骑的速度会根据你的骑术等级和所在区域改变。"}}
D.SpellTexts[139603]={Description={["dc84a52006f11d5b:45"]="让一个夺日者法力收集器超载并摧毁它。"}}
D.SpellTexts[139629]={Aura={["979997f4ce4e183b:8"]=S[13681]}}
D.SpellTexts[139635]={Description={["e92a04afbd2d894e:51"]=S[13359]}}
D.SpellTexts[139639]={Aura={["85114f9a6b0472a5:32"]="可以使用奥术强化技能。"}}
D.SpellTexts[139642]={Description={["4b31e8d820b8130b:125"]=S[13274]}}
D.SpellTexts[139657]={Description={["de0da1b6b3f7fc3f:32"]="召唤来自于墓地之下的生物。"}}
D.SpellTexts[139683]={Description={["9a94b87211eeb74d:29"]="从奥术风暴处吸取能量。"}}
D.SpellTexts[139696]={Description={["170bd44289ab553f:58"]="向融合之煞投掷闪电长枪，并消灭它。"}}
D.SpellTexts[139714]={Description={["4ee24eec2a4c8cbb:46"]="被一只鹰勒住，缓慢窒息。"}}
D.SpellTexts[139724]={Description={["647994c70afc3878:39"]=S[2356]}}
D.SpellTexts[139732]={Description={["6f9d052785518522:41"]="试图从喀岱的魔爪中挣脱！"}}
D.SpellTexts[139736]={Description={["32c460b0d2e1ffbb:40"]="让一个肯瑞托法力焦镜超载并摧毁它。"}}
D.SpellTexts[139770]={Description={["783d4cfe8d262055:18"]="打开一个风暴之箱。"}}
D.SpellTexts[139772]={Description={["e808cbbbca98dcda:24"]="正在引导星辰打击。"},Aura={["e808cbbbca98dcda:24"]="正在引导星辰打击。"}}
D.SpellTexts[139773]={Description={["4160350185e824fc:173"]="虽然掌握着强大的魔法，但魔古族还是喜欢驱使奴隶来建造雄伟的纪念碑。这个基座上记载了为了建造这样一座纪念碑所牺牲的奴隶的数量。"}}
D.SpellTexts[139776]={Description={["9e6b1ca47527909b:173"]="“虽然螳螂妖在日常生活中会用到风绒和帝王丝绸，但他们还是更偏向于使用各种各样的昆虫翅膀（包括他们自己的）来制作“流行”服饰。这面旗帜就是很好的佐证。”"}}
D.SpellTexts[139777]={Description={["c1cab4ee08b4df91:86"]="一次势大力沉的野蛮攻击，对施法者面前的所有敌人造成物理伤害，并使其昏迷。"},Aura={["979997f4ce4e183b:8"]=S[13681]}}
D.SpellTexts[139779]={Description={["35ee1610a7fa9f85:163"]="螳螂妖更青睐于成年的凯帕圣树树脂，而他们正是利用这些设备来进行采集的。通过对这个古代器具的观察，你会发现它的设计构造并没有随时间的流逝而改变。"}}
D.SpellTexts[139780]={Description={["0e47e0f8c73ab4b7:166"]="“这座卡拉克西瓦塑像几乎可以追溯到上古泰坦时期。塑像底座上刻有献给“七首之神”的祷文。“卡拉克西”在古代语中意为“祭司””。"}}
D.SpellTexts[139781]={Description={["f6e81851b1547e44:184"]="对非螳螂妖种族而言，螳螂妖的声波信标技术非常晦涩难懂，似乎是和螳螂妖的某种生理机能紧密相关。这个古代信标虽然完好无损，但没有螳螂妖的互动便无法使用。"}}
D.SpellTexts[139782]={Description={["7880e32719ead5de:171"]="显然这套琥珀保存办法并不是万无一失的，这位英杰只残存下了头颅。尽管要测算出具体年代几乎是不可能的，但看上去要早于熊猫人起义的时候。"}}
D.SpellTexts[139783]={Description={["f78f220d82e40e3a:96"]="灯笼里透出来的光并不是火焰，也不是魔法。其中，你可以看到许多发光的昆虫，被储存在琥珀里。"}}
D.SpellTexts[139784]={Description={["53e43d8228bd44b3:86"]="这个物件的用途很难说清楚，看上去似乎是某种花粉采集器。"}}
D.SpellTexts[139785]={Description={["ecc66a2036430ea7:126"]="这个容器看上去是琥珀的颜色，但其实是用恐虫分泌物制成的。这样的器皿在螳螂妖居室中真是再常见不过了。"}}
D.SpellTexts[139786]={Description={["47bb851177154b00:339"]="这把古代的“掠天弯刀”本是为飞行螳螂妖所打造的武器：它的质地很轻，平衡感上佳，适合那些从天空俯冲下来的攻击者以圆弧状挥砍的技法。绝大多数螳螂妖在拥有足够力量穿上重型铠甲，挥舞重型武器时，都会卸下翅膀来作为一种仪式——所以像这样巧夺天工的轻型武器非常稀有。这可能曾经为一个英杰所使用。"}}
D.SpellTexts[139787]={Description={["eb17f909d03e68aa:317"]="相较于一般的种族来说，螳螂妖能制造或收听音频更宽的声音。他们与生俱来的对这种极高或极低音频的了解，使得螳螂妖能将音波作为武器来使用。该装置所产生的音波脉冲能将肌肉和器官从细胞层面瓦解。若直接被击中，则五脏六腑都会被震得粉碎。"}}
D.SpellTexts[139790]={Description={["04f250096cd35d70:56"]="跳向一个敌人的位置，对冲击区域造成奥术伤害。"}}
D.SpellTexts[139792]={Aura={["832c28e0607af305:30"]="这家伙正在拖运宝藏！"}}
D.SpellTexts[139799]={Description={["1839134ac43038bb:84"]="召唤一道火焰喷射，使玩家迷惑5秒，并造成大量的火焰伤害。"},Aura={["2d32a0a8a9968ddb:8"]=S[14976]}}
D.SpellTexts[139800]={Description={["1ce0110aeb1151cb:52"]="造成中等的物理伤害，并将敌人击退。"}}
D.SpellTexts[139801]={Description={["023bc5eb6c02a3aa:75"]="召唤一道闪电打击，对敌人造成大量的自然伤害，并使其速度降低50%。"},Aura={["9c31a7c1d64a9b6e:7"]=S[3025]}}
D.SpellTexts[139804]={Description={["a4e07bf840c34b4d:54"]=S[9589]},Aura={["9c31a7c1d64a9b6e:7"]=S[3025]}}
D.SpellTexts[139844]={Description={["979997f4ce4e183b:8"]=S[13681]},Aura={["979997f4ce4e183b:8"]=S[13681]}}
D.SpellTexts[139853]={Description={["fbca3ccc69c021e9:45"]="从天空召唤威力巨大的闪电箭。"}}
D.SpellTexts[139857]={Description={["58bfb078717450c5:27"]="寒冰洪流正瞄准你！"},Aura={["58bfb078717450c5:27"]="寒冰洪流正瞄准你！"}}
D.SpellTexts[139882]={Description={["a04b8101cdbffbc6:99"]="万能犁会将鬼鬼祟祟的兔妖轰出被占据的土壤，降低它们的生命值，并迷惑5秒。"},Aura={["c7350e89be6d9a1a:48"]="被万能犁轰出去，并迷惑。"}}
D.SpellTexts[139894]={Description={["5c615581aeeb0280:59"]="施法者向目标掷出锁链，造成物理伤害。"}}
D.SpellTexts[139913]={Aura={["badd5ccb7a52e042:75"]="霍嘎克会制造出急速膨胀或收缩的毁灭气旋。"}}
D.SpellTexts[139919]={Aura={["80103e34cb5eb5c1:82"]="一位带有物质交换效果的玩家距离你很远。一旦被驱散，你将会和他们交换位置。"}}
D.SpellTexts[139929]={Description={["fb6c7ef289396205:71"]=S[16255]}}
D.SpellTexts[139932]={Description={["051f3a9f92f0573a:51"]=S[5509]}}
D.SpellTexts[139933]={Description={["051f3a9f92f0573a:51"]=S[5509]}}
D.SpellTexts[139934]={Description={["051f3a9f92f0573a:51"]=S[5509]}}
D.SpellTexts[139964]={Description={["c381e229988dfefa:106"]="融合之煞释放出无边无际的黑暗光环笼罩世界，对天界生物造成了极大伤害。"}}
D.SpellTexts[139966]={Aura={["979997f4ce4e183b:8"]=S[13681]}}
D.SpellTexts[139975]={Description={["1cb339a86770521b:72"]="在一片区域中抛撒一把欢歌铃种子，将其播种在最多4块开垦过的小块土壤上。"}}
D.SpellTexts[139977]={Description={["2ab47a6890f22c05:73"]="在一片区域中抛撒一把毒蛇茎种子，将其播种在最多4块开垦过的小块土壤上。"}}
D.SpellTexts[139978]={Description={["76a83b2347119258:70"]="在一片区域中抛撒一把谜之种，将其播种在最多4块开垦过的小块土壤上。"}}
D.SpellTexts[139981]={Description={["2e67cf918abc8b18:72"]="在一片区域中抛撒一把魔法鳞茎种子，将其播种在最多4块开垦过的小块土壤上。"}}
D.SpellTexts[139983]={Description={["162c72ba7c7f6c01:79"]="在一片区域中抛撒一把风剪仙人掌种子，将其播种在最多4块开垦过的小块土壤上。"}}
D.SpellTexts[139985]={Aura={["62cb3b85ec886da2:47"]=S[2546]}}
