D.SpellTexts[140040]={Description={["d1dc085b9a7d8000:189"]="用异域皮来制成华丽毛皮，每天只能制作一次。在此过程中，你对潘达利亚制皮工艺的了解可能会有所提高，从而发现一个全新的图样。与华丽制鳞秘诀共享冷却时间。"}}
D.SpellTexts[140041]={Description={["1f7a429b57f23e8a:192"]="用棱彩鳞片来制成华丽毛皮，每天只能制作一次。在此过程中，你对潘达利亚制皮工艺的了解可能会有所提高，从而发现一个全新的图样。与华丽制皮秘诀共享冷却时间。"}}
D.SpellTexts[140046]={Description={["6fc2bb7191361db4:115"]="当意识到自己在独自面对天界防御者时，融合之煞会引导其黑暗能量来放逐天界防御者。"},Aura={["88856127fbcd51d2:61"]="无法行动。\r\n对融合之煞所造成的任何伤害都会打断该效果。"}}
