D.SpellTexts[142037]={Description={["92588a9f96ab32b2:113"]="火炮将你列为了主要目标。\r\n\r\n出来混，总是要还的。\r\n骰子已被掷出。\r\n命运也作出了选择。\r\n大海要吞噬你的灵魂！"},Aura={["6c9fd5f023e56a75:23"]="火炮正在瞄准你！"}}
D.SpellTexts[142058]={Description={["c35bf4e017a681fb:57"]="你们这些咸湿的老水手最好趁大海吞噬你们之前赶紧逃命吧！"},Aura={["b3efad315a0e7662:29"]="数门火炮正向你射击！"}}
D.SpellTexts[142059]={Description={["853c7de957fe2c4e:41"]="这副古怪的骰子似乎不再起作用了。"},Aura={["38f2e676e0a55a07:26"]="已掷过受诅咒的海盗骰子。"}}
D.SpellTexts[142060]={Description={["49a0bd55249b05e4:56"]="被诅咒的骰子翻落在地，对目标造成伤害。"}}
D.SpellTexts[142061]={Description={["62f7d922ff2f8c3b:76"]="啊，朋友！\r\n\r\n现如今，骰子站在了你这边，想要帮你对抗这些咸湿的老水手！"}}
D.SpellTexts[142072]={Aura={["ef7ec73ecb8d7323:52"]="炸弹启动，一触即发。\r\n\r\n别碰这个工兵！"}}
D.SpellTexts[142073]={Description={["4637d3b2d282c8f9:86"]="召唤或解散一匹炉石天马。这种坐骑的速度会根据你的骑术等级和所在区域改变。"}}
D.SpellTexts[142098]={Aura={["25366c6a8c3c115f:28"]="被赐予惊人的力量。"}}
