D.SpellTexts[142241]={Description={["90be0cbe399bfdbd:35"]="炫耀你的搏击成就。"}}
D.SpellTexts[142242]={Description={["ea8721b673f70343:31"]="夸耀你战胜了锋齿。"}}
D.SpellTexts[142243]={Description={["90be0cbe399bfdbd:35"]="炫耀你的搏击成就。"}}
