D.SpellTexts[142406]={Description={["107b652bda3975d0:92"]="点燃施法者的武器，并在每次近战攻击命中后，在敌方目标的脚下生成余烬之池。"},Aura={["691ef7c493e99cc7:55"]="近战攻击命中后，有一定几率生成余烬之池。"}}
D.SpellTexts[142416]={Description={["9d15a379d929c9ac:165"]="伊约库克会在数个敌人之间施放火焰光束。若两个受害者距离位置越近，火焰光束造成的伤害就越高，同时还会对其行进路线上的玩家造成伤害。"},Aura={["5c351ff59281da9c:55"]="你和所有站在炎界行进路线上的盟友会受到火焰伤害。"}}
D.SpellTexts[142438]={Description={["ddb269f44366033f:29"]="击退冲击波附近的所有人。"}}
