D.SpellTexts[142478]={Description={["2677085c7a95d1e7:69"]="召唤或解散一只可供骑乘的蓝色装甲龙鹰。这是一种飞行坐骑。"}}
D.SpellTexts[142499]={Description={["553df6b0dff82e9b:30"]=S[12046]}}
D.SpellTexts[142514]={Description={["f51db1dd022fda52:152"]="施法者获得伊约库克的能力，可以看到所有事物的数值，并将其归纳。维持一个主要数值，施法者的伤害就会得到显著提升。"}}
D.SpellTexts[142517]={Description={["791d6855101641d8:35"]="赋予友方玩家一个随机数值。"}}
D.SpellTexts[142518]={Description={["9ba056ffbffb7d52:56"]="吸收一名友方玩家已被测算出来的数值，添加给你自己。"}}
D.SpellTexts[142523]={Description={["a0807d964a622333:87"]="记录所有你已取得的数值。维持一个主要数值，你的伤害就会提升！"}}
