D.SpellTexts[142668]={Description={["908f9932039ff6cf:90"]="施法者控制一个敌人的心灵，并迫使其走向附近一只饥饿的恐虫。"}}
D.SpellTexts[142671]={Description={["335225bf4da9dba2:163"]="操纵者卡兹提克强迫受害者走向其中一头饥饿的恐虫。如果受害者接触到恐虫会立即死亡，并且恐虫会从幼虫蜕化为成虫。"},Aura={["39d27522fc585cdf:37"]="被魅惑。\r\n跑向一头饥饿的恐虫。"}}
