D.SpellTexts[142771]={Description={["254b966e7565d7cd:55"]="践踏地面，使得施法者脚下的大地分崩离析。"}}
D.SpellTexts[142773]={Description={["e4b126f87a4cf8e5:45"]="向一名敌人冲锋，并使其脚下的地面分崩离析。"}}
