D.SpellTexts[142817]={Description={["9825ac735ec22804:63"]=S[10055]}}
D.SpellTexts[142819]={Description={["c1b839433c0511bc:59"]="一次冰冷的寒风冲击，对目标造成自然伤害，并将其击退。"}}
D.SpellTexts[142825]={Description={["703629df8dfbe326:73"]="施法者喷射出寒冰碎片，冲击5码范围内的敌人，造成冰霜伤害。"}}
D.SpellTexts[142828]={Aura={["06d18798a4f87115:40"]=S[294]}}
D.SpellTexts[142833]={Aura={["80e06934245eaf1f:68"]="一个强大的幻影，会试图为受重伤的盟友进行治疗。"}}
D.SpellTexts[142834]={Aura={["0c2d124ca75d28c1:33"]="一个简单的幻影，喜欢成群结队。"}}
D.SpellTexts[142835]={Aura={["fd857271c9064e90:55"]="一个幻影，会周期性地制造一个飘向敌人的琥珀宝珠。"}}
D.SpellTexts[142836]={Aura={["db6fce1a53b06579:82"]="一个防御型幻影，会偏转来自正面的所有攻击，并周期性更改朝向。"}}
D.SpellTexts[142837]={Aura={["69832bc2828e17d7:137"]="一个极其坚韧的幻影，拥有一个能暂时减免所受伤害的强力护盾。护盾消失后，幻影会暂时性变得脆弱。"}}
D.SpellTexts[142838]={Aura={["3625041f16919824:53"]="一个短命的幻影，会在自爆前四处游荡。"}}
D.SpellTexts[142839]={Aura={["8c369d0f75b9e0b0:71"]="一个四处飞窜的幻影，会在远处向敌人投掷香蕉。"}}
D.SpellTexts[142848]={Description={["8f6cf0ea0e04cadf:15"]="彻底被腐蚀！"},Aura={["8f6cf0ea0e04cadf:15"]="彻底被腐蚀！"}}
D.SpellTexts[142869]={Description={["4935094ea8d75d6b:17"]="争夺PvP区域。"},Aura={["743d335ae542764d:63"]="该区域当前正处在PvP争夺中，仅限于等级不低于85级的玩家。"}}
D.SpellTexts[142976]={Description={["827c34d201f1b23b:161"]="用两块华丽毛皮来制成强化华丽毛皮，每天只能制作一次。在此过程中，你对熊猫人制皮工艺的了解可能会有所提高，从而发现一个全新的图样。"}}
D.SpellTexts[142877]={Description={["e7925e9bc4f881ee:200"]="激活目标的抗体进行恢复，数值相当于接受的治疗量。\r\n下一次该目标受到伤害时，天然再生系统将被激活，为目标恢复，数值相当于储存的治疗量。"}}
D.SpellTexts[142878]={Description={["36f49f387a959e37:94"]="召唤或解散一条魔法灵龙。这种坐骑的速度会根据你的骑术等级和所在区域改变。"}}
D.SpellTexts[142880]={Description={["5224c837fa673c64:79"]="右键点击以召唤或解散你的繁花古树。该宠物会随着四季变换而改变。"}}
D.SpellTexts[142897]={Description={["2e597cd427979391:67"]="为目标进行治疗，数值相当于不稳定的药膏所储存的治疗量。"}}
D.SpellTexts[142901]={Description={["211c977334f08114:61"]="打开满满的英雄宝箱，赢取丰厚奖赏！"}}
D.SpellTexts[142902]={Description={["5fe084caa5d79a79:71"]="这枚火箭会把你带到荒芜之地，速度飞快哦。\r\n\r\n你要不要试试？"},Aura={["6886bcf3d300ead4:14"]="火箭飞人！"}}
D.SpellTexts[142910]={Description={["86cc84e098c6901d:51"]="召唤或解散一匹可供骑乘的铁箍鬼灵战马。"}}
D.SpellTexts[142918]={Aura={["3d9c06be473a736d:112"]="克尔鲁克的攻击将受害者的血管暴露在外，使其更容易受到毒心者夏克里尔的毒害。"}}
D.SpellTexts[142920]={Description={["1dea56b8b3b046c9:39"]="呼风唤雨。只能在北贫瘠之地使用。"}}
D.SpellTexts[142922]={Description={["6a3541d1db51d66a:87"]=S[2639]}}
D.SpellTexts[142927]={Description={["73ba08fc7d3c764b:106"]=S[7939]},Aura={["73ba08fc7d3c764b:106"]=S[7939]}}
D.SpellTexts[142929]={Description={["2dd3a1a90bb42e7a:107"]="夏克里尔的攻击会令受害者的肌体变得脆弱，使其更容易受到掠风者克尔鲁克的攻击伤害。"}}
D.SpellTexts[142931]={Description={["6a3541d1db51d66a:87"]=S[2639]}}
D.SpellTexts[142933]={Description={["5c1563c93a685c14:90"]="在地上放置一个空的赞达拉补给箱。只能在雷电之王的藏宝库场景战役中使用。"}}
D.SpellTexts[142948]={Aura={["b9a517653ff53966:33"]="希赛克瞄准技能的当前目标。"}}
D.SpellTexts[142983]={Aura={["57a8e0be476a124b:76"]="每秒造成越来越高的暗影伤害。被驱散时会跳至其他目标身上。"}}
D.SpellTexts[143011]={Description={["0c7d9a2e09022099:104"]="用风绒布卷来织成神纹布，每天只能制作一次。在此过程中，你可能会发现一个尚未学会的图样。"}}
D.SpellTexts[143020]={Description={["73838201684ffa56:194"]=S[3566]},Aura={["73838201684ffa56:194"]=S[3566]}}
D.SpellTexts[143027]={Description={["1d586ba276c2ba69:115"]="鲁克·石趾和一名敌人同时冲锋并在半途相撞。然后，鲁克·石趾将立刻施放蚀骨回旋踢。"},Aura={["b19d612f147cd824:28"]="和鲁克·石趾对冲。"}}
D.SpellTexts[143199]={Description={["0a766085f0d5074e:42"]="马尔考罗克将上古毒瘴从他的体内驱逐出来。"}}
D.SpellTexts[143217]={Description={["5f45652faa02f88e:101"]=S[9479]}}
D.SpellTexts[143219]={Description={["f374eaf5aa71910c:82"]="附近的爆炸使得这片区域开始着火。站在火中会受到持续的火焰伤害。"},Aura={["b651cd9dabd48228:28"]=S[15456]}}
D.SpellTexts[143220]={Description={["3fb5c6f6a488a3ff:93"]=S[7332]}}
D.SpellTexts[143221]={Description={["cf6c21a4706856b1:59"]=S[1373]},Aura={["cf6c21a4706856b1:59"]=S[1373]}}
D.SpellTexts[143243]={Description={["66aa121ccc9604ff:103"]="施法者向随机方向射出数道音波脉冲，每个方向只能选择一次。"},Aura={["bb7bf34addb4b1db:18"]="发射音波脉冲。"}}
D.SpellTexts[143255]={Description={["2382db74bba960cf:134"]="用延极锭来锻造两仪延极锭。在此过程中，你可能会发现一个尚未学会的锻造设计图。每天只能制作一次。"}}
D.SpellTexts[143256]={Description={["d97419e6ab3f0bc9:30"]="你的坐骑将变成钢铁战马。"},Aura={["d97419e6ab3f0bc9:30"]="你的坐骑将变成钢铁战马。"}}
D.SpellTexts[143273]={Aura={["a425e31e9d0c4659:122"]="斯基尔的巨型刀刃将其受害者的脏器暴露在外，使其更容易成为里卡尔残暴实验的牺牲品。"}}
D.SpellTexts[143274]={Description={["1ded9f1287d23b9d:139"]=S[13188]}}
D.SpellTexts[143275]={Description={["8c7e82df040f245c:138"]=S[13188]}}
D.SpellTexts[143277]={Aura={["c2de735c8836ad59:170"]="里卡尔多年来对螳螂妖奴隶的实验，使其能够随意更改受害者的基因组成。\r\n里卡尔的受害者们会发现他们的肉体很容易受到觅血者斯基尔攻击的影响。"}}
D.SpellTexts[143278]={Description={["704e06d4b5982e87:83"]=S[20829]}}
D.SpellTexts[143279]={Description={["704e06d4b5982e87:83"]=S[20829]}}
D.SpellTexts[143280]={Description={["45593da48b9071eb:169"]="施法者挥舞武器打出强力一击，导致受害者的鲜血散落在房间各处，并形成小型血球。这些血球会向附近的一名英杰移动，并为其治疗。"}}
D.SpellTexts[143292]={Description={["ad6063a4ddf626e5:49"]="锁定一个随机玩家并展开攻击，直到被嘲讽。"}}
D.SpellTexts[143294]={Description={["5c41fff32627c79a:42"]="为目标治疗，数值基于施法者的生命值。"}}
D.SpellTexts[143309]={Description={["e99b063ef4fc748d:72"]=S[1342]},Aura={["e99b063ef4fc748d:72"]=S[1342]}}
D.SpellTexts[143313]={Description={["8ba399108535a2ad:42"]="使用地精传送器离开怒焰裂谷。"}}
D.SpellTexts[143319]={Aura={["af0ad5c7e14cafaa:72"]="攻击会生成血滴，若盟友穿过血滴则会被治疗。"}}
D.SpellTexts[143320]={Description={["5f45652faa02f88e:101"]=S[9479]}}
D.SpellTexts[143321]={Description={["997a2633b33529f0:87"]="在目标位置处生成血滴。盟友接触血滴可为其恢复生命。"}}
D.SpellTexts[143324]={Description={["857a9460875f1189:38"]="附近存在着霜火元素之灵。"},Aura={["857a9460875f1189:38"]="附近存在着霜火元素之灵。"}}
D.SpellTexts[143325]={Description={["8624cbcffd271f2c:60"]=S[18140]}}
D.SpellTexts[143330]={Aura={["d86312dd54a6efe2:14"]=S[16999]}}
D.SpellTexts[143336]={Description={["dba5b4807aeb8ca7:73"]="里卡尔将含有遗传基因的注射器随机扔向一个目标，使其产生变异。"}}
D.SpellTexts[143337]={Aura={["19be941bbc74927a:25"]="你现在是一只卡拉克西巨蝎。"}}
D.SpellTexts[143338]={Description={["fdde8b120bbbb4b7:67"]=S[387]}}
D.SpellTexts[143340]={Description={["953793bc5443d1e7:82"]="注射的药剂在离开受害者的血管后发生反应，生成数个琥珀寄生虫。"}}
D.SpellTexts[143355]={Aura={["beabe32c31ec4dc7:56"]="这个生物每10秒会恢复100%的生命值。"}}
D.SpellTexts[143356]={Description={["f1c48fd900754076:21"]="施法者恢复满生命值。"}}
D.SpellTexts[143358]={Description={["d430a6d03ab55951:32"]=S[13421]},Aura={["4f98b1d8393d0727:8"]=S[19106]}}
D.SpellTexts[143368]={Description={["69ecd83168a2faf8:16"]="熊猫人，通用语。"},Rank={["f3c10a8cf576c267:13"]=S[18948]}}
D.SpellTexts[143369]={Description={["0bf014d055c69045:16"]="熊猫人，兽人语。"},Rank={["f3c10a8cf576c267:13"]=S[18948]}}
D.SpellTexts[143370]={Description={["c4fac883e88de00c:42"]="装死，摆脱敌人的纠缠。"},Aura={["a5c53f404e75c7cb:14"]="装死。"}}
D.SpellTexts[143377]={Description={["63f29f881b269715:49"]=S[9173]}}
D.SpellTexts[143380]={Description={["645c050df71280a8:30"]=S[9112]}}
D.SpellTexts[143382]={Aura={["bbefd0c0124340c1:92"]=S[16103]}}
D.SpellTexts[143401]={Description={["59be69032b683e3a:78"]="一股死亡能量向外扩散而出，对所有元素爪牙造成严重伤害。"}}
D.SpellTexts[143411]={Description={["ca927eaf5f4a1d96:34"]=S[12519]},Aura={["ca927eaf5f4a1d96:34"]=S[12519]}}
D.SpellTexts[143414]={Description={["b706a818585cbd9d:42"]="在附近的戈隆尸体上放置霜狼军旗。"}}
D.SpellTexts[143419]={Description={["b706a818585cbd9d:42"]="在附近的戈隆尸体上放置霜狼军旗。"}}
D.SpellTexts[143428]={Aura={["979997f4ce4e183b:8"]=S[13681]}}
D.SpellTexts[143433]={Description={["49a8e94eca7a4413:35"]=S[21313]}}
D.SpellTexts[143440]={Description={["63d0df75b57eed90:64"]="该单位陷入了血性狂乱！移动速度会周期性提高。"},Aura={["63d0df75b57eed90:64"]="该单位陷入了血性狂乱！\r\n移动速度会周期性提高。"}}
D.SpellTexts[143442]={Description={["91c47a9cbc73d99f:93"]="施法者随时间逐渐变强大，提高伤害输出和移动速度，可叠加。\r\n\r\n免疫嘲讽。"}}
D.SpellTexts[143445]={Description={["25048672e77216f7:33"]="索克嗅到了你的血腥味，并开始追击你！"},Aura={["80d20cdeec0add1b:30"]="被锁定。\r\n施法者免疫嘲讽。"}}
D.SpellTexts[143449]={Aura={["8973f8638c9c8674:40"]="贾纳尔和他的流亡者准备骑乘上路。"}}
D.SpellTexts[143452]={Description={["57f5bf9d033a4bf2:21"]="你身上满是鲜血的味道！"},Aura={["57f5bf9d033a4bf2:21"]="你身上满是鲜血的味道！"}}
D.SpellTexts[143465]={Description={["2f7bbb71164209b8:9"]="吞噬。"}}
D.SpellTexts[143469]={Description={["0382980ce2b5338d:66"]=S[20850]},Aura={["0382980ce2b5338d:66"]=S[20850]}}
D.SpellTexts[143474]={Description={["d83e04188313b3e7:48"]=S[5234]}}
D.SpellTexts[143480]={Aura={["5bfa7b2c625a89dd:26"]="一个刺客盯上了你！"}}
D.SpellTexts[143483]={Description={["e9ed78f81465e83b:105"]="卡拉克西众英杰的终极目标眼看即将到手，此刻他们的斗志绝不会轻易退却。\r\n\r\n为施法者恢复满生命值。"}}
D.SpellTexts[143484]={Aura={["024b4d9907145efe:33"]="无法使用消耗怒气的技能。"}}
D.SpellTexts[143501]={Description={["577ac9b380ece82c:78"]=S[17565]}}
D.SpellTexts[143506]={Description={["d7f50690467c5eed:11"]=S[11912]}}
D.SpellTexts[143507]={Description={["d7f50690467c5eed:11"]=S[11912]}}
