D.SpellTexts[143509]={Description={["d7f50690467c5eed:11"]=S[11912]}}
D.SpellTexts[143523]={Description={["26720fcbb1452470:9"]="已净化。"},Aura={["26720fcbb1452470:9"]="已净化。"}}
D.SpellTexts[143535]={Aura={["3f671625d48038aa:47"]="攻击命中后会为纳兹戈林将军产生怒气值。"}}
D.SpellTexts[143536]={Description={["577ac9b380ece82c:78"]="竖立一面军旗，使盟友的攻击为纳兹戈林将军恢复额外的怒气。"},Aura={["2bf9d3ede4b3cece:36"]="令盟友受到库卡隆军旗的效果。"}}
D.SpellTexts[143542]={Aura={["eaf2cad8098047c3:39"]="这个英杰接下来会加入战斗。"}}
D.SpellTexts[143546]={Description={["a3243cc308d207ba:157"]="孙·柔心召唤出守护者的恶念，以形成颓丧的化身和绝望的化身。\r\n\r\n这些灵魂会持续攻击玩家，直到它们全部被消灭。"},Aura={["7fc1275983d79b96:11"]="冥想中。"}}
D.SpellTexts[143562]={Description={["2cb561211030997c:44"]=S[9258]},Aura={["2cb561211030997c:44"]=S[9258]}}
D.SpellTexts[143570]={Aura={["921f562ff4b921d2:43"]="效果消失时开始狂奔。"}}
D.SpellTexts[143572]={Aura={["bb27e04ce782ab79:22"]="开始狂奔。"}}
D.SpellTexts[143574]={Description={["7e91ca8385345ec6:149"]="傲气膨胀用单体技能攻击目标以削弱其腐蚀，并在附近形成一个凝结煞能，对攻击者造成膨胀腐蚀效果。"},Aura={["e6191dbcd2f8a127:86"]="单体技能会在附近召唤一个凝结煞能，对攻击者造成膨胀腐蚀效果。"}}
