D.SpellTexts[143636]={Description={["d60299b89179ccaf:48"]="从你前方的地面上召唤出一排琉璃尖刺。"}}
D.SpellTexts[143637]={Description={["963b1311dcfa41ce:36"]="右键点击以召唤或解散泽拉达尔。"}}
D.SpellTexts[143650]={Description={["028156dbf2df3a02:38"]="方向舵没有反应——我们要掉下去啦！"},Aura={["052c241812fe6f8b:37"]="方向舵没有反应——要掉下去啦！"}}
D.SpellTexts[143654]={Description={["eb2213c9fce51642:59"]="野火将雷神补给品点着后火势发展迅猛。"}}
D.SpellTexts[143678]={Description={["0aabf578ed705edb:24"]="你脸上满是虫血。"},Aura={["0aabf578ed705edb:24"]="你脸上满是虫血。"}}
D.SpellTexts[143686]={Description={["1e4a2a4f329a2104:148"]="玩家被灌输毒心者夏克里尔渊博的炼金学识。任何直接对友方目标进行的治疗都会试图为其清除夏克里尔的毒素。"},Aura={["155805af80ac42ee:53"]="直接治疗会为附近的盟友移除夏克里尔的基础毒素。"}}
D.SpellTexts[143703]={Description={["7ab78a90964f288f:39"]="右键点击以召唤或解散你的淘气机器人。"}}
D.SpellTexts[143709]={Description={["26776ce1fcc0762a:75"]="卡诺兹蓄势待发，以迅雷不及掩耳之势向战场内的随机敌人发起冲锋。"}}
D.SpellTexts[143721]={Description={["94edf821f4676b86:11"]="自我回收"}}
D.SpellTexts[143732]={Description={["a577ff8dc921a25c:52"]="右键点击以召唤或解散卡夫帝。这个宠物棒极了。"}}
D.SpellTexts[143745]={Description={["71ee74d4fbaf4799:194"]="颓丧的化身和绝望的化身将它们的负面情感集中起来，制造出邪煞具象攻击玩家。这些情感具象受到任意伤害时，也会使生成它们的主体遭受同样伤害。"},Aura={["a29af1bbfa216078:24"]="与制造者共享生命值。"}}
D.SpellTexts[143759]={Description={["7ebe4eb7555e5d44:66"]="施法者准备将数块琥珀掷向他的敌人。"},Aura={["50c16113bc3a03a6:13"]="投掷琥珀。"}}
D.SpellTexts[143765]={Description={["af4baa5d4b72c348:52"]="施法者利用嗓音，向某片区域发射音波。"}}
D.SpellTexts[143800]={Aura={["5f50ecba77749003:58"]="凛冽刺骨。叠加到5层时，你将被冻结在寒冰之墓中。"}}
D.SpellTexts[143807]={Description={["e782cac2181dba61:46"]=S[16930]}}
D.SpellTexts[143812]={Description={["6c9599d6f487dbfd:176"]="禾·软足召唤出他兄弟的恶念，以形成苦痛的化身，它会锁定团队中带有苦痛印记的成员。\r\n\r\n该灵魂会持续攻击玩家，直到它被消灭。"},Aura={["7fc1275983d79b96:11"]="冥想中。"}}
D.SpellTexts[143818]={Description={["380a051cf0a92b0b:71"]=S[7465]},Aura={["380a051cf0a92b0b:71"]=S[7465]}}
D.SpellTexts[143825]={Description={["079832d24a89ffad:31"]="将一大块肉丢到肉堆里去。"}}
D.SpellTexts[143828]={Aura={["c6d68db7ff6375da:20"]="一道激光锁定了你。"}}
D.SpellTexts[143834]={Aura={["1a03c6693857a4ac:12"]="打断。"}}
D.SpellTexts[143839]={Description={["6a346c92a7e03ff5:20"]=S[2073]}}
D.SpellTexts[143840]={Description={["88e0729dc4f7d5f8:290"]="苦痛印记每秒会对目标周期性造成暗影伤害，并将其定身。\r\n\r\n当苦痛的化身攻击目标时，会施加暗影虚弱效果，提高苦痛印记所造成的伤害。此外，传播苦痛印记会对所有玩家施加一层暗影虚弱。该效果可叠加。\r\n\r\n苦痛的化身已锁定了你！"},Aura={["75d21b8d4ac273fe:80"]="每秒造成越来越高的暗影伤害。\r\n苦痛的化身已锁定了你！\r\n被定身。"}}
D.SpellTexts[143842]={Description={["c46b8562cfc5716d:39"]="将印记转移给另一个友方玩家。"}}
D.SpellTexts[143852]={Description={["7a090d5a7dcd8e63:44"]="向一名敌人射出一团火球，造成火焰伤害。"}}
D.SpellTexts[143853]={Description={["01c364a89a8b11e1:60"]="向一名敌人投掷石块，对附近所有的敌人造成物理伤害。"}}
D.SpellTexts[143864]={Description={["9825ac735ec22804:63"]=S[10055]}}
D.SpellTexts[143878]={Description={["6a346c92a7e03ff5:20"]=S[2073]}}
D.SpellTexts[143882]={Description={["e653c27acd4bf099:35"]="标记一个目标，将其锁定。"},Aura={["98d0700ab954313b:23"]="一个狙击手盯上了你！"}}
