D.SpellTexts[143911]={Description={["2ca5077e49922673:101"]="使你的伤害和治疗技能有一定几率立即触发一次相当于1/3伤害量或治疗量的额外效果。"}}
D.SpellTexts[143912]={Description={["1adad0341fe22c45:36"]="造成一次伤害量为最近一次攻击伤害1/3的攻击。"}}
D.SpellTexts[143914]={Description={["393895722eded761:101"]="减少冲动、影舞步、暗影之刃、暗影斗篷、闪避和烟雾弹的冷却时间。"}}
D.SpellTexts[143916]={Description={["669c45526e686413:22"]="杀死附近的所有敌人。"}}
D.SpellTexts[143917]={Description={["bf924599e42a2684:39"]="打开加尔鲁什兽栏里的一个笼子。"}}
D.SpellTexts[143922]={Description={["123e750205bee935:22"]="提高奔跑速度。"}}
D.SpellTexts[143923]={Description={["3b2529ab82fd544c:63"]="你所造成的所有伤害按一定百分比转化为生命值。"}}
D.SpellTexts[143924]={Description={["62f9b233faa779ba:14"]="生命值被汲取。"}}
D.SpellTexts[143927]={Description={["189876bd7297e372:58"]="受到的所有范围攻击伤害减少一定百分比。"}}
D.SpellTexts[143928]={Description={["688bb2aa19ab462f:46"]="因死亡导致的耐久度减少降低一定百分比。"}}
D.SpellTexts[143931]={Description={["ddce87dfe3f63578:107"]="使你的攻击可以立即对附近所有目标进行一次额外攻击并造成相同的伤害。"}}
D.SpellTexts[143932]={Description={["a0b63e4325c8a8e2:37"]=S[1856]},Aura={["a0b63e4325c8a8e2:37"]=S[1856]}}
D.SpellTexts[143939]={Description={["35b2103e9d9e2897:74"]="使目标昏迷，紧接着立即挥舞双刃对受害者进行猛烈打击。"},Aura={["d86312dd54a6efe2:14"]=S[16999]}}
D.SpellTexts[143941]={Description={["4218b5239123258e:32"]="对目标造成数次伤害。"}}
D.SpellTexts[143951]={Aura={["b51235fdebbc44d0:20"]=S[7761]}}
D.SpellTexts[143955]={Description={["fab06d7172738c12:171"]="鲁克·石趾召唤出亲密伙伴的恶念，以形成困苦的化身、悔恨的化身和阴郁的化身。\r\n\r\n这些灵魂会持续攻击玩家，直到它们全部被消灭。"},Aura={["7fc1275983d79b96:11"]="冥想中。"}}
D.SpellTexts[143964]={Description={["c0b17b95e87d953c:19"]="跳至附近的平台。"}}
D.SpellTexts[143974]={Aura={["979997f4ce4e183b:8"]=S[13681]}}
D.SpellTexts[143977]={Description={["a17a251fdbd6e730:86"]="至尊者柯尔凡对其前方进行数次打击，对该区域内的任意目标造成伤害。"},Aura={["ed14a5edef311974:39"]="攻击施法者前方的任意目标。"}}
D.SpellTexts[143990]={Aura={["e4a0c05d14cef510:26"]="污水喷涌正在瞄准你！"}}
D.SpellTexts[143999]={Description={["43292afe9fb65e13:55"]="玩家无法治疗或复活他们的战斗宠物。"},Aura={["b185bf4099cd0cb9:43"]="宠物在战斗以外无法被复活或治疗。"}}
D.SpellTexts[144013]={Description={["917092ba6dcf7eff:150"]="召唤出古代锦鱼人水灵的灵魂，并试图净化目标身上的所有邪恶和戾气。这个古代咒法对其受害者具有嘲讽效果。"}}
D.SpellTexts[144014]={Description={["4107afc22a95a5cf:99"]="召唤出古代野牛人火焰之王的灵魂。这个古代咒法对其受害者具有嘲讽效果。"}}
D.SpellTexts[144016]={Description={["eb8f4cb936f77354:76"]="召唤克洛斯圣灵来制服附近的恐龙。\r\n\r\n其结果难以预料……"}}
D.SpellTexts[144025]={Description={["33c69738e34d9db9:53"]=S[9415]}}
D.SpellTexts[144031]={Description={["9849396e432f8031:49"]="对冲击范围内的生物造成物理伤害。"},Aura={["9849396e432f8031:49"]="对冲击范围内的生物造成物理伤害。"}}
D.SpellTexts[144052]={Description={["05a40f6ae2f5ed7f:39"]="将施法者变成一个水晶怪物。"},Aura={["eb323c8eeeea2d39:63"]="将施法者变成一个水晶怪物。\r\n幽灵们变得不友好起来。"}}
D.SpellTexts[144070]={Description={["47831e91cd24129c:28"]="召唤一道余烬元素之墙。"}}
D.SpellTexts[144076]={Aura={["1ff8ea9e0337a3af:39"]="周期性地向敌人射出闪电。"}}
D.SpellTexts[144084]={Aura={["06d18798a4f87115:40"]=S[294]}}
D.SpellTexts[144085]={Aura={["0c2d124ca75d28c1:33"]="一个简单的幻影，喜欢成群结队。"}}
D.SpellTexts[144086]={Aura={["44ddb1d5641b56f4:75"]="一个幻影，来无影去无踪，会造成大量伤害，但生命值较低。"}}
D.SpellTexts[144087]={Aura={["cef871230789cb50:53"]="一个幻影，会周期性反击，并降低威胁。"}}
