D.SpellTexts[144091]={Aura={["30912ac1440823a2:70"]=S[293]}}
D.SpellTexts[144092]={Aura={["b84d468b76c812be:50"]="格洛坦高傲地扛着雷神氏族军旗。"}}
D.SpellTexts[144093]={Description={["e15c559c7883808b:48"]="贾纳尔斩击目标，立即杀死他们。"},Aura={["dffce5323b02a8db:42"]="阻碍了贾纳尔的复仇行动。"}}
D.SpellTexts[144095]={Description={["9240ec0d35ca8718:49"]="施法者将目标记录在测算列表中。"}}
D.SpellTexts[144103]={Description={["0bf0e54766ca7918:55"]=S[18066]}}
D.SpellTexts[144111]={Description={["8dd7092cee859781:69"]="测算和初始目标拥有相同条件的所有目标，为其进行治疗。"}}
D.SpellTexts[144114]={Description={["dec053a5108de5aa:147"]="一次凶狠扫击，将一名敌人与其战场上的盟友隔绝开来。\r\n\r\n将当前目标10码范围内的敌人击退，并使其流血。"}}
D.SpellTexts[144115]={Description={["5b5d6c69bc8fb45e:74"]="用烈焰为武器附魔，使施法者的攻击偶尔会造成额外的火焰伤害。"},Aura={["10770e9c198498d9:45"]=S[12859]}}
D.SpellTexts[144145]={Description={["ed4e78c00dec1afd:31"]="部分身体浸没在幽魂虚空。"},Aura={["ed4e78c00dec1afd:31"]="部分身体浸没在幽魂虚空。"}}
D.SpellTexts[144175]={Aura={["29bdf35db4dd90f4:35"]="让附近的灵魂看起来更可怕。"}}
D.SpellTexts[144176]={Description={["dc30e27bcd09557c:83"]="苦痛的化身攻击时会造成暗影虚弱效果，提高苦痛印记所造成的伤害。"},Aura={["5563200c3bd76dcd:36"]="提高苦痛印记所造成的伤害。"}}
