D.SpellTexts[144640]={Description={["f090d27c1558653f:22"]="扑向一个远处的目标。"}}
D.SpellTexts[144216]={Description={["6d09c7e4a629bf1f:61"]="使受害者更易受到诡异之雾所造成的进一步伤害。"}}
D.SpellTexts[144226]={Aura={["7e303575f1d9823a:24"]="和哈洛姆共享生命值。"}}
D.SpellTexts[144227]={Aura={["08380b21ebbcf358:25"]="和卡德里斯共享生命值。"}}
D.SpellTexts[144229]={Description={["b00172be0be1b1b3:60"]="试图打开一个装有潘达利亚失窃神器的箱子。"},Aura={["692ae512ecc6b1eb:11"]="要破了……"}}
D.SpellTexts[144236]={Aura={["a7c1b8958f9793f2:37"]="通过编译器识别。\r\n可使用管道。"}}
D.SpellTexts[144267]={Aura={["937c8f76a3e5f185:36"]="护甲降低，周期性自然伤害。"}}
D.SpellTexts[144286]={Description={["457fc0746428123d:29"]="立即杀死一只琥珀寄生虫。"}}
