D.SpellTexts[144358]={Description={["27b53af925996938:84"]="伤害一名敌人，使其每次遭受傲之煞的近战伤害时都将获得5点傲气值。"},Aura={["9a4c61549bdb07d5:40"]="遭受傲之煞的近战攻击会获得5点傲气值。"}}
D.SpellTexts[144370]={Description={["30ddba3b33a36852:41"]="死亡时给距离最近的2名敌人5点傲气值。"}}
