D.SpellTexts[144433]={Description={["77d59c51055037c6:62"]="召唤一股强劲的水柱，将附近的目标击飞至空中。"}}
D.SpellTexts[144441]={Description={["51918bda9a571a29:160"]="你的致死打击和嗜血有一定几率激活死亡裁决，可对生命值高于20%的目标使用斩杀。对于生命值低于20%的目标，死亡裁决可使斩杀不消耗怒气值。"}}
D.SpellTexts[144443]={Aura={["afc3ee22d05394af:27"]=S[1569]}}
