D.SpellTexts[146421]={Description={["b679b40f7f4478dc:83"]="制作一碗汤面。这种清汤挂面对于囊中羞涩的学徒来说很是实惠。"}}
D.SpellTexts[146422]={Description={["f16f997f3f7d968e:122"]="制作一碗龙须汤面。不同种类的蔬菜经过微妙搭配后，其独特的风味令往来商人和店主们赞不绝口。"}}
D.SpellTexts[146423]={Description={["a615e23fbe85bde0:140"]="制作一碗熊猫人八宝汤面。这种汤面用料丰盛，营养价值极高，是辛劳一天后迅速恢复体力和精神的不二之选。"}}
D.SpellTexts[146428]={Description={["7e583ebf4a8db722:61"]="为任意天神善行披风注入拉希奥的龙族精华。"}}
