D.SpellTexts[146441]={Aura={["7225f9a7a9e61ff8:65"]="这碗汤面用了许多不同种类的香料和蔬菜，其独特风味令人垂涎三尺。"}}
D.SpellTexts[146442]={Aura={["9883e2445aa418d3:78"]="这碗汤面用料丰盛，营养价值极高，适用于高强度劳作后恢复体力。"}}
