D.SpellTexts[152218]={Description={["b0b71e2a2521e9f1:37"]="掐住目标，造成大量伤害。"},Aura={["0adaaa780c653bdb:16"]="掐住目标。"}}
D.SpellTexts[152235]={Aura={["660b8706d9fe846f:15"]=S[6322]}}
D.SpellTexts[152251]={Description={["ac1d064b1cdabbee:56"]=S[6209]}}
D.SpellTexts[152258]={Description={["bfa658b7400589a0:79"]="喷射出一股毒性棘刺，对所有敌方目标造成相当于500%武器伤害的自然伤害。"}}
D.SpellTexts[152282]={Description={["5cbe4101bfc8a7fc:101"]="经过短暂蓄力后重击地面，造成自然伤害并击退目标。"},Aura={["be1f5d6d57b09868:41"]="造成物理伤害。\r\n击退目标。"}}
D.SpellTexts[152297]={Description={["292998e422c7b6e3:18"]="你可以在水面上行走！"},Aura={["292998f122c7b6f0:18"]=S[1571]}}
D.SpellTexts[152303]={Description={["5b9a707f884175b0:84"]="将鱼人泥浆丢在暮光之锤异教徒的身上，使其变成令阿库麦尔无法抗拒的美味。"},Aura={["dff011b39bd37b72:56"]="趁鱼人泥浆还新鲜时，丢在暮光之锤异教徒的身上！"}}
D.SpellTexts[152324]={Description={["c80a032dd6e9b946:81"]=S[12923]},Aura={["bc1acf864e9976c3:83"]=S[12923]}}
D.SpellTexts[152327]={Aura={["9910f5f8e390527b:31"]="跟着奥克默克回到厄隆绿洲。"}}
