D.SpellTexts[152374]={Aura={["af7dd3e535f36e38:43"]="你誤入禁地，已被移出。"}}
D.SpellTexts[152387]={Aura={["97d0118ab3c8fcef:33"]="偏转来自前方的所有攻击。"}}
D.SpellTexts[152421]={Description={["c1738d943e61bb3d:43"]="你可以乘坐这个魔法冰块横渡江河。"},Aura={["82a468e3bc0e6326:107"]="使你获得能够随冰块漂流的能力。\r\n\r\n在漂流过程中跳跃可以划动冰块，使你的移动速度最多提高130%。"}}
