D.SpellTexts[152453]={Description={["c308770cc8e8168f:23"]="生命值恢复10%。"},Aura={["175ffd03983596d8:29"]="伊基什为你恢复10%的生命值。"}}
D.SpellTexts[152507]={Description={["a7cba34915b922f0:83"]="在地上丢下内含7颗炸弹的炸药包，对附近的所有敌人造成火焰伤害。"}}
D.SpellTexts[152510]={Description={["3213a32c3b7d45fb:81"]=S[5228]},Aura={["4c11f480a208583d:62"]=S[18529]}}
