D.SpellTexts[152520]={Description={["79cf01f8ae24d7df:40"]="在目标身上覆满易燃的黑火药。"},Aura={["98c273d2ae90170d:128"]="身上沾有极其易燃的黑火药。\r\n任何火焰伤害都会导致燃烧效果，造成伤害并使你失控般到处乱跑。"}}
D.SpellTexts[152521]={Description={["e09c139a9a06309d:49"]="用高爆远距离火药点燃目标。"}}
D.SpellTexts[152530]={Description={["8b6028da07e17ec7:41"]="把一名敌人从钢铁切割者上甩下去。"}}
D.SpellTexts[152536]={Description={["c097fe14ad9932b3:98"]=S[13302]}}
D.SpellTexts[152571]={Description={["0031677c562ebf57:61"]="对攻击者前方小锥形范围内的敌人造成物理伤害。"}}
