D.SpellTexts[152954]={Description={["5904e319894a03d4:88"]="生成一段神圣能量裂缝，对滞留在神圣之地内的敌人造成神圣伤害。"},Aura={["34e9d999e99da5cc:27"]="周期性造成神圣伤害。"}}
