D.SpellTexts[152973]={Aura={["1e15afbf1ffc83ec:27"]="保护盟友免受伤害。"}}
D.SpellTexts[152985]={Description={["3ab7a7aff0532024:70"]="将附近一个增能转存为你的储备增能。\r\n\r\n需要材料：竞速转换器。"}}
