D.SpellTexts[153025]={Aura={["a377f761bbecff40:46"]="使用电池技能来释放所储存的增能。"}}
D.SpellTexts[153054]={Aura={["cf4690132a8ebd28:15"]="邪火喷发"}}
D.SpellTexts[153061]={Description={["322cb2b942debe30:51"]="使用：教你学会建造诊所（3级）。"}}
