D.SpellTexts[153168]={Aura={["093675fc5e568ec1:66"]="极不情愿装作被俘的样子，前往石槌奴隶营地寻找伊瑞尔。"}}
D.SpellTexts[153251]={Description={["cc2f68cacc8f3441:52"]="迷惑附近的迷你飞艇。\r\n\r\n需要材料：竞速转换器。"}}
D.SpellTexts[153253]={Aura={["3902644d115b38bc:12"]=S[20345]}}
D.SpellTexts[153260]={Description={["d92739b6e67f84a1:82"]="一块打磨过的水晶，会随着时间逐步提高装备者的爆击几率。"}}
D.SpellTexts[153262]={Description={["38feb753eedb1a18:60"]="一块抛光过的水晶，会周期性为装备者提供防护。"}}
D.SpellTexts[153265]={Description={["236e057461dd32ff:86"]="一块共鸣晶体，会监测装备者的生命体征，并产生数个治疗能量之池。"},Aura={["772f36364cdd391d:85"]="每秒恢复1%的生命值。\r\n\r\n受到伤害时每隔3秒会产生一个治疗能量之池。"}}
D.SpellTexts[153269]={Description={["24afadce31f35b79:30"]="踩扁一个小兽人，狠狠地踩！"}}
D.SpellTexts[153273]={Aura={["979997f4ce4e183b:8"]=S[13681]}}
D.SpellTexts[153310]={Description={["7bfc16ee9bf9992b:58"]="向敌人施放晕眩之击，降低其最大移动速度。"},Aura={["82405d0bae5dca08:21"]=S[17404]}}
