D.SpellTexts[153383]={Aura={["f0d08f7342c4c22c:63"]="从黑暗之门发出的诡异腥红能量使你无法飞行。"}}
D.SpellTexts[153386]={Aura={["ece4fca50a3b6e12:69"]="摧毁附肢可以对阿库麦尔造成伤害，并使其在短时间内昏迷。"}}
D.SpellTexts[153387]={Description={["8be01b3ab6b76ad3:44"]="为某些暗月竞速赛技能制造材料。"}}
