D.SpellTexts[153413]={Aura={["125a475ed34eb6d9:48"]="你全身覆盖着狼血。移动受限。"}}
D.SpellTexts[153477]={Description={["44ca8ae5570476a8:125"]="扭曲已故德莱尼的灵魂，在指定位置形成数个会造成暗影伤害的漩涡。漩涡中心是安全位置。"},Aura={["b93e0cc1b47c088e:29"]="扭曲已故德莱尼的灵魂。"}}
D.SpellTexts[153480]={Aura={["c8acb52e32d79d1f:23"]="阻挡视线与移动。"}}
D.SpellTexts[153489]={Description={["7d02098301c87b9e:89"]="召唤或解散一头钢铁碎天兽。这种坐骑的速度会根据你的骑术等级和所在区域改变。"}}
D.SpellTexts[153499]={Description={["54f97459b9774444:51"]="阿扎凯尔重击地面，生成一片充满恶魔能量的池子。"}}
D.SpellTexts[153503]={Description={["85f658278a46ff5c:41"]="召唤一个机器人嘲讽附近的迷你飞艇。"}}
D.SpellTexts[153504]={Description={["885d48c650e21751:38"]=S[2257]}}
D.SpellTexts[153505]={Description={["885d48c650e21751:38"]=S[2257]}}
D.SpellTexts[153506]={Description={["885d48c650e21751:38"]=S[2257]}}
