D.SpellTexts[153896]={Description={["5c48e9fe2aa87f83:101"]="施法者发出尖啸，刺穿区域内所有敌人的耳膜。对施法者发动近战攻击将结束该效果。"},Aura={["6b2c88bc35680ba9:45"]="对所有敌人大声尖啸，造成物理伤害。"}}
