D.SpellTexts[153905]={Description={["5a9ef362464c53a9:108"]="在施法者身旁召唤出一个回旋风暴向前移动，对其路径上的所有敌人造成物理伤害。"}}
D.SpellTexts[153923]={Description={["25d41792c07fb6e5:53"]="施法者强化了附近一只恐惧渡鸦，使其追击敌人。"},Aura={["1529835b5dbdeaa0:40"]="这只恐惧渡鸦会追击一个随机敌人。"}}
D.SpellTexts[153926]={Description={["ce778f7927445282:66"]="施法者强化了附近所有被驯服的卡利鸟，使其追击敌人并自爆。"},Aura={["05d508ff33666b0a:46"]="这只卡利鸟会追击一个随机敌人并自爆。"}}
D.SpellTexts[153954]={Description={["acd6ec874da90d92:114"]="施法者在一名随机玩家头上召唤一个拜日狂信徒试图将其带离阳台并扔下去。"}}
D.SpellTexts[153977]={Description={["647b08dd9189d49a:19"]="收割一个生者的灵魂。"},Aura={["29970289f8ecce00:19"]="吸取生命能量。"}}
