D.SpellTexts[154139]={Description={["51ff9347d8865e22:139"]="施法者将光线聚焦在鸦人炎阳构装体上为其进行治疗。玩家可以站在光线前予以阻挡，但此举会遭受到火焰伤害。"},Aura={["3a39fd1415df5dd3:38"]=S[9822]}}
