D.SpellTexts[154312]={Description={["feb091057269c34e:172"]="吐息之喉被激活后，毒影会喷吐污浊吐息打击前方锥形区域内的所有敌人。\r\n\r\n击杀吐息之喉将阻止毒影继续使用污浊吐息。"},Aura={["12d37dc3401c1474:77"]="吐息之喉被激活。\r\n\r\n当吐息之喉被激活时，毒影会使用污浊吐息。"}}
D.SpellTexts[154313]={Description={["660ea4ce638df73f:131"]="粉碎之颅被激活后，毒影会对附近的目标进行近战攻击。\r\n\r\n击杀粉碎之颅将阻止毒影继续进行近战攻击。"},Aura={["d9ff8aa0f8c3bb07:79"]="粉碎之颅被激活。\r\n\r\n当粉碎之颅被激活时，毒影会使用近战攻击。"}}
D.SpellTexts[154317]={Description={["48fc62e0ff881391:83"]="为一个受伤的头颅进行再生。20秒后头颅恢复正常并继续进行攻击。"},Aura={["d1a37271f5ca5806:51"]="再生。\r\n\r\n该头颅在被治愈前不可使用。"}}
