D.SpellTexts[155167]={Description={["c7a628cee2e54d45:92"]="遁入暗影界，藏匿行踪并能抽取逝网爬行者身上的腐化物。"},Aura={["785be2184a7b4481:10"]=S[21317]}}
D.SpellTexts[155176]={Description={["6b77821c5755b1fd:68"]="施法者举起一个凝聚了元素之力的护盾，使其免疫所有伤害。"},Aura={["7a8d3eb9f126fd5c:18"]=S[2689]}}
