D.SpellTexts[155213]={Description={["232a79d225296567:109"]="熔渣元素能量达到100点时会复活。复活后的熔渣元素会随机挑选一名敌人进行锁定。"}}
D.SpellTexts[155219]={Description={["adb6420c0a1638b7:127"]="施法者种下一颗不谐之种，失效时会发生爆炸。不谐之种施放时其持续时间随机而定。"},Aura={["729da1e47623a9f3:27"]="失效时会发生爆炸。"}}
D.SpellTexts[155229]={Aura={["1f88ac60635ee673:67"]="被恶魔法术所腐化。只有在暗影界下才能被抽取。"}}
D.SpellTexts[155233]={Aura={["4d3babccbc0614e9:46"]="一旦热能达到100点将会重新投入战斗。"}}
D.SpellTexts[155240]={Description={["bab04ee348a991b2:217"]="暴露在山脉之心的攻击所造成的热能下会逐步提高所受伤害。当暴露在比你当前淬火层级和任意初始热能还要高的热能层级下时，使用淬火只会增强该效果。"}}
D.SpellTexts[155241]={Description={["e202b39850de4321:20"]=S[20534]}}
D.SpellTexts[155256]={Description={["d70fdf1869d00007:52"]="提高施法者对元素生物造成的伤害。"},Aura={["6ef7f27dacd578dc:40"]="对元素生物造成额外伤害。"}}
D.SpellTexts[155263]={Description={["b715f42186b6f7a2:16"]=S[20528]}}
D.SpellTexts[155268]={Description={["9ffc57144e8453ff:38"]=S[5770]}}
D.SpellTexts[155275]={Aura={["40f8267ea360622f:48"]="将火焰能量储存进她的利刃中，使其攻击力得到加强。"}}
D.SpellTexts[155279]={Description={["3ee0f12ccf3f529b:45"]="向敌人投掷利斧，造成大量伤害。"}}
D.SpellTexts[155288]={Description={["fb272e219bb4ea76:163"]="元素之怒的热能相当高，以至于爆裂熔炉临近区域内的所有生物都会受到周期性火焰伤害。元素之怒获得的热能越高，冲击波的频率就越快。"}}
D.SpellTexts[155572]={Aura={["979997f4ce4e183b:8"]=S[13681]}}
D.SpellTexts[155315]={Description={["65572de6e2f51de5:88"]="你与区域内的火焰产生共鸣。敌人的脚下有时会喷发出一道熔岩之柱。"},Aura={["6a40823e34badb7b:55"]="敌人的脚下有时会喷发出一道熔岩之柱。"}}
D.SpellTexts[155323]={Description={["6f6a672d344014d2:66"]="将敌人沿随机方向击退，并开始石化过程。"}}
D.SpellTexts[155330]={Description={["e38bc72c40589839:42"]=S[19489]}}
D.SpellTexts[155334]={Description={["7493771c103d7f51:76"]="你与区域内的冰霜产生共鸣。你的出现有时会导致敌人被冻结。"},Aura={["33d82e0938b09c38:44"]="你的出现有时会导致敌人被冻结。"}}
D.SpellTexts[155335]={Description={["7b962a07cf9fde2c:36"]="将区域内的敌方目标冻结5秒。"},Aura={["7b962a07cf9fde2c:36"]="将区域内的敌方目标冻结5秒。"}}
D.SpellTexts[155344]={Description={["6a05b7f0096a371f:112"]="你受到了霜火岭之风的祝福。有一定几率获得飞沙走石，产生100%急速和飘浮效果。"},Aura={["0ecd0a7641ec5def:72"]="你有一定几率获得飞沙走石增益，得到100%急速和飘浮效果。"}}
