D.SpellTexts[158619]={Description={["5358f06008b05b5b:92"]="将敌人定身在原地。\r\n\r\n免疫移动限制效果时不会阻止或移除该效果。"},Aura={["56353fc0b7105e6d:7"]=S[18981]}}
D.SpellTexts[158638]={Description={["9f22a1e0a5a1d115:98"]=S[10578]}}
