D.SpellTexts[158659]={Description={["4ff35458579fd88f:107"]="施法者对敌人位置投掷武器随后将其召回。被武器击中的敌人将受到物理伤害。"}}
D.SpellTexts[158661]={Aura={["3d5f525655e289c5:26"]=S[15366]}}
D.SpellTexts[158664]={Description={["8ab4502a9ec8e52f:96"]="猛击地面，对冲击点附近的敌人造成物理伤害，并削弱其战斗力。"}}
D.SpellTexts[158665]={Description={["e0e2049a6fc337ed:46"]="猛踢一名敌人，造成伤害并将其击退。"}}
