D.SpellTexts[158693]={Aura={["10eefc3528f8d48c:22"]="钓鱼技能提高100点。"}}
D.SpellTexts[158694]={Description={["64c881b71093b2a2:89"]="施法者猛击前方的地面，对直线上的所有敌人造成暗影伤害。"}}
D.SpellTexts[158700]={Description={["1147fb2496ef9cad:106"]="制造两道相互冲击的火墙，并立即杀死触碰到的任意目标。"}}
D.SpellTexts[158701]={Description={["6371a091105b3282:82"]="高莱克呼叫增援，从无畏舰的船舱内召唤出一名钢铁开膛者。"}}
D.SpellTexts[158702]={Description={["2fbcee17f586c79a:88"]="钢铁开膛者把注意力集中在一名随机玩家身上，并且只会攻击被其锁定的目标。"},Aura={["bd19582825fe1c41:27"]="开膛者正在追踪你！"}}
D.SpellTexts[158703]={Aura={["c5aa9b81f72c8ad8:44"]="每秒对所有敌人造成奥术伤害。"}}
D.SpellTexts[158704]={Description={["490eaa068d82f1cf:107"]="施法者制造一件可以在附近生成暗影能量场的法器。进入其中的玩家将受到暗影伤害。"},Aura={["0f270140a26c7019:42"]="进入该区域的玩家将受到暗影伤害。"}}
D.SpellTexts[158707]={Description={["329041cfad6647a4:82"]="罗格召唤一摊庇护之土。任何进入其中的盟友都会获得土之壁垒效果。"}}
D.SpellTexts[158711]={Aura={["cabd1e3f3e2cb9ce:24"]=S[15364]}}
D.SpellTexts[158716]={Description={["1ce63c16504182a9:90"]="使附魔师可以为武器和护甲附加德拉诺的魔法效果，技能上限为700点。"}}
D.SpellTexts[158719]={Description={["d9dab2a454a8a677:164"]=S[13270]}}
D.SpellTexts[158720]={Description={["fc377a144fd76887:11"]="丢火把"}}
D.SpellTexts[158728]={Description={["7a09566da0d998b2:142"]="施法者制造一件可以汲取附近敌人生命力的法器。站在这些法器附近的玩家将受到暗影伤害并使施法者恢复生命值。"}}
D.SpellTexts[158731]={Description={["ea18bd39a1854f88:187"]="乌克罗格被玛拉卡的黑暗之血魔法扭曲，不断散发出邪恶的能量。\r\n\r\n当乌克罗格活着时，这股能量会导致在无畏舰上的所有玩家周期性地在脚下自动生成堕落之血池。"},Aura={["bf96616c4228e509:54"]="周期性在玩家脚下生成堕落之血池。"}}
D.SpellTexts[158735]={Description={["1a15a6282b3af9b7:15"]=S[15767]}}
D.SpellTexts[158737]={Description={["4cf2edbc8d4932f1:70"]="使铁匠可以制造武器和护甲，技能上限为700点。"}}
D.SpellTexts[158739]={Description={["d4824d9842bf1b7f:95"]="使工程学技师可以制造绝大部分情况下能够正常工作的炸弹和机械，技能上限为700点。"}}
D.SpellTexts[158741]={Description={["41cd4c74c66ac21d:103"]="使医师可以制造并使用绷带，技能上限为700点。需要从人型生物身上获得的布料。"}}
D.SpellTexts[158745]={Description={["19166b13d9d3829c:77"]="寻找并采集德拉诺的奇异草药。使你的草药学技能上限提高到700点。"}}
D.SpellTexts[158748]={Description={["3d821808173803cb:69"]="使铭文师可以制造魔法铭文物品，技能上限为700点。"}}
D.SpellTexts[158752]={Description={["637f5f022fdbd309:85"]="使制皮师可以制造顶级品质的皮甲，技能上限为700点。"}}
D.SpellTexts[158754]={Description={["ddbcb9d479ed5f95:75"]="你能在德拉诺古老的大地上采集矿石。采矿技能上限为700点。"}}
D.SpellTexts[158756]={Description={["ef2109f2253e54c1:48"]="可以从德拉诺的野兽身上剥皮以用于制皮。"}}
D.SpellTexts[158758]={Description={["91762ca536a19fd2:78"]="使裁缝可以制造无与伦比的优质衬衣和布甲，技能上限为700点。"}}
D.SpellTexts[158762]={Description={["379d35e15bfbae20:96"]="考古学家可以收集神器碎片，并将这些碎片拼合成完整的古代神器，可达到的技能上限为700点。"}}
D.SpellTexts[158765]={Description={["e1e3f09ec14dcd19:73"]="可以学习德拉诺的烹饪食谱，你的技能最多提高到700点。"}}
